function ICN(name,size,color){ const s=size||22; return '<svg viewBox="0 0 24 24" width="'+s+'" height="'+s+'" fill="none" stroke="'+(color||'currentColor')+'" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'+(ICONS[name]||'')+'</svg>'; }
/* Icône par groupe musculaire — remplace les anciens emojis décoratifs des exercices par les
   icônes SVG du même style que le reste de l'app (voir ICONS ci-dessus). */
const MUSCLE_ICON_MAP={'Pectoraux':'dumbbell','Pectoraux bas':'dumbbell','Pectoraux haut':'dumbbell','Dos':'back','Grand dorsal':'back','Lombaires':'back',
  'Épaules':'shoulders','Trapèzes':'shoulders','Deltoïde latéral':'shoulders','Deltoïde antérieur':'shoulders','Arrière épaules':'shoulders','Cou':'shoulders',
  'Biceps':'arms','Triceps':'arms','Avant-bras':'arms',
  'Quadriceps':'legs','Ischios':'legs','Adducteurs':'legs','Abducteurs':'legs','Mollets':'legs',
  'Fessiers':'glutes','Abdominaux':'abs','Obliques':'abs','Transverse':'abs','Core':'abs',
  'Corps entier':'run'};
function muscleIconName(group){ return MUSCLE_ICON_MAP[group]||'dumbbell'; }
function exGlyph(e,size){ const g=(e&&((e.muscles&&e.muscles[0])||(e.primary&&e.primary[0])||e.group))||'Corps entier'; return ICN(muscleIconName(g),size||28,'var(--e)'); }
/* colored rounded-square icon badge used in card headers, replaces flat emoji */
function cardIcon(name,color){ color=color||'var(--e)'; return '<span class="icb" style="background:linear-gradient(145deg,color-mix(in srgb,'+color+' 13%,transparent),color-mix(in srgb,'+color+' 5%,transparent));box-shadow:0 0 0 1px color-mix(in srgb,'+color+' 20%,transparent) inset,0 4px 10px -4px color-mix(in srgb,'+color+' 33%,transparent);color:'+color+'">'+ICN(name,15,color)+'</span>'; }

// Images des 8 paliers de badges encodées en base64 directement dans le code
// (comme le logo IKORUN) : plus de fichiers .png séparés à servir/déployer,
// tout est déjà présent dès que app.js est chargé — demande explicite du 20/09.
const BADGE_IMG_FILES={
  debutant:'badges/rank_debutant.png',
  amateur:'badges/rank_amateur.png',
  sportif:'badges/rank_sportif.png',
  athlete:'badges/rank_athlete.png',
  expert:'badges/rank_expert.png',
  elite:'badges/rank_elite.png',
  maitre:'badges/rank_maitre.png',
  legende:'badges/rank_legende.png'
};
function bdGlyph(key){
  if(window.ikIsRankKey && ikIsRankKey(key)) return ikRankSVG(key);   // 8 rangs : SVG (ui/rank-badges.js)
  const src=BADGE_IMG_FILES[key];
  if(!src) return '<span class="bd-emoji">'+ICN(badgeEmoji(key),28,'var(--e)')+'</span>';
  return '<img class="bd-glyph" src="'+src+'" alt="" draggable="false" loading="lazy" data-key="'+key+'" onerror="bdImgErr(this)">';
}
function badgeEmoji(key){ const b=BADGE_TIERS.find(x=>x.key===key); return (b&&ICONS[b.emoji])?b.emoji:'medal'; }
// Image embarquée en base64 : plus de retry réseau possible, on bascule direct
// sur l'icône si jamais le décodage échoue (data corrompue).
function bdImgErr(img){
  const key=img.dataset.key;
  const span=document.createElement('span'); span.className='bd-glyph bd-emoji'; span.innerHTML=ICN(badgeEmoji(key),28,'var(--e)');
  img.replaceWith(span);
}

/* ---------- OUTILS — HUB ÉPURÉ ---------- */
let outilsTab='home';
function TOOLS_DEF(){ return {
  aio:{name:t('toolAioName'),sub:t('toolAioSub'),icon:ICN('lab'),fn:'renderAIO'},
  sante:{name:t('toolSanteName'),sub:t('toolSanteSub'),icon:ICN('health'),fn:'renderSanteTool',hidden:true},   // V4.7 : vit dans Stats › Santé
  chrono:{name:t('toolChronoName'),sub:t('toolChronoSub'),icon:ICN('stopwatch'),fn:'renderChrono'},
  convert:{name:t('toolConvertName'),sub:t('toolConvertSub'),icon:ICN('convert'),fn:'renderConvertTool'},
  notes:{name:t('toolNotesName'),sub:t('toolNotesSub'),icon:ICN('note'),fn:'renderNotesTool'},
  // accessibles via recherche
  vdot:{name:t('toolVdotName'),sub:t('toolVdotSub'),icon:ICN('lung'),fn:'renderVDOTtool'},
  imc:{name:t('toolImcName'),sub:t('toolImcSub'),icon:ICN('scale'),fn:'renderIMC'},
  hydra:{name:t('toolHydraName'),sub:t('toolHydraSub'),icon:ICN('water'),fn:'renderHydraTool'},
  bmr:{name:t('toolBmrName'),sub:t('toolBmrSub'),icon:ICN('fire'),fn:'renderBMRtool'},
  // 7 outils musculation deja codes et traduits en interne (labels de champs)
  // mais jamais enregistres ici -> jamais accessibles depuis le menu. Meme
  // logique "accessibles via recherche" que vdot/imc/hydra/bmr ci-dessus.
  rm:{name:t('toolRMName'),sub:t('toolRMSub'),icon:ICN('dumbbell'),fn:'renderRMtool'},
  tonnage:{name:t('toolTonnageName'),sub:t('toolTonnageSub'),icon:ICN('chart'),fn:'renderTonnageTool'},
  calories:{name:t('toolCaloriesName'),sub:t('toolCaloriesSub'),icon:ICN('fire'),fn:'renderCaloriesTool'},
  prog:{name:t('toolProgName'),sub:t('toolProgSub'),icon:ICN('bolt'),fn:'renderProgTool'},
  pomodoro:{name:t('toolPomodoroName'),sub:t('toolPomodoroSub'),icon:ICN('timer'),fn:'renderPomodoro'},
  load:{name:t('toolLoadName'),sub:t('toolLoadSub'),icon:ICN('target'),fn:'renderLoadTool'},
  repos:{name:t('toolReposName'),sub:t('toolReposSub'),icon:ICN('pause'),fn:'renderReposTool'},
  agenda:{name:t('toolAgendaName'),sub:t('toolAgendaSub'),icon:ICN('calendar'),fn:'renderAgenda',hidden:true},
  priere:{name:t('toolPriereName'),sub:t('toolPriereSub'),icon:ICN('mosque'),fn:'renderPriere',hidden:true}
}; }
// TOOLS est recalculé à chaque affichage pour suivre la langue active (voir renderOutils/outilsHome)
let TOOLS=TOOLS_DEF();
const MAIN_TOOLS=['aio','chrono'];
/* 18/09 : seuls 5 outils sur 18 etaient navigables sans passer par la
   recherche (3 MAIN_TOOLS + 2 OTHER_TOOLS) -- les 11 autres (dont les 7
   outils muscu cables plus tot dans la journee) n'existaient que si on savait
   deja leur nom exact a taper. 'agenda' en particulier n'avait ABSOLUMENT
   aucun autre point d'entree nulle part dans le code (contrairement a
   'priere', qui garde sa carte dediee sur l'accueil via openPrayerFromHome()
   -- access deja meilleur qu'une tuile de grille, laisse tel quel). Grille
   complete desormais : tout outil non cache reste a une recherche pres, mais
   plus BESOIN de chercher pour le decouvrir. */
const OTHER_TOOLS=['convert','notes','vdot','imc','hydra','bmr','rm','tonnage','calories','prog','pomodoro','load','repos','agenda'];
function toolFav(){ return (PREFS.favTools||['aio','chrono','convert','notes']).filter(k=>k!=='sante'); }
function toggleFav(k){
  let f=toolFav(); f=f.includes(k)?f.filter(x=>x!==k):[...f,k]; PREFS.favTools=f; saveAll(); renderOutils();
  // La sauvegarde était bien immediate, mais si ce toggle vient de l'etoile dans
  // l'overlay "Modifier les favoris" (editFavs()), renderOutils() ne redessine
  // que la page Outils EN DESSOUS, invisible tant que l'overlay reste ouvert —
  // ses propres etoiles restaient donc figees jusqu'a fermeture/reouverture.
  // Trouve lors de l'audit du 20/09.
  if($('#ovSettings') && $('#ovSettings').classList.contains('on')) editFavs();
}
let toolSearch='';
function recentTools(){ return PREFS.recentTools||[]; }
function pushRecent(k){ let r=recentTools().filter(x=>x!==k); r.unshift(k); PREFS.recentTools=r.slice(0,4); saveAll(); }
function renderOutils(){
  TOOLS=TOOLS_DEF(); ikIslandKick();
  let h='';
  if(outilsTab==='home'){ h=outilsHome(); swapIn('s-outils',h); bindToolSearch(); return; }
  if(outilsTab==='_timer'){ renderOutilsTimer(); return; }
  const tl=TOOLS[outilsTab]; if(!tl){ outilsTab='home'; return renderOutils(); }
  h='<div class="row" style="margin-bottom:14px"><button class="x" onclick="outilsBack()" aria-label="'+t('back')+'">‹</button><div class="man tool-title" style="font-weight:800;font-size:'+(tl.name.length>18?'15px':'17px')+';flex:1;text-align:center;margin:0 8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+tl.name+'</div><button class="x" onclick="toggleFav(\''+outilsTab+'\')" aria-label="'+t('favoriteLab')+'" style="color:'+(toolFav().includes(outilsTab)?'var(--or)':'var(--dim)')+'">'+ICN('star',17)+'</button></div><div id="outBody"></div>';
  swapIn('s-outils',h);
  window[tl.fn] && window[tl.fn]();
}
let outilsFrom='home';
function outilsBack(){
  if(outilsFrom==='_back'){ outilsTab='home'; outilsFrom='home'; return nav(_outilsEntry||'home'); }
  outilsTab=outilsFrom||'home'; outilsFrom='home'; renderOutils();
}
function openTool(k){
  pushRecent(k); outilsFrom=outilsTab; outilsTab=k;
  // L'outil IMC gardait pour toujours ses valeurs par défaut (175cm/62kg) : `imc`
  // est initialisé une seule fois au chargement du script, avant que le profil
  // asynchrone (P.height/P.weight) n'ait eu le temps de charger. On resynchronise
  // donc depuis le profil à chaque ENTREE fraîche dans l'outil — jamais dans
  // renderIMC() elle-même, qui est aussi appelée par les boutons +/-, sinon ils
  // seraient annulés à chaque clic. Trouvé lors de l'audit du 20/09.
  if(k==='imc' && P){ if(P.height) imc.h=P.height; if(P.weight) imc.w=P.weight; }
  renderOutils(); $('#scroll').scrollTop=0;
}
// Seule la liste sous le champ se redessine à chaque lettre : avant, toute la page (champ
// compris) était recréée, ce qui faisait clignoter le clavier sur iPhone.
function bindToolSearch(){ const si=$('#toolSearchInp'); if(si){ si.oninput=()=>{ toolSearch=si.value; const r=$('#toolRes'); if(r) r.innerHTML=outilsList(); }; } }
function outilsHome(){
  // La VDOT est affichée dans Sport, Stats et Profil : plus de pastille ici (retour du 26/09).
  let h='';
  // Raccourcis rapides Chrono + Minuteur
  h+='<div style="display:flex;gap:10px;margin-bottom:16px"><div class="card" style="flex:1;padding:14px;margin:0;cursor:pointer;text-align:center" onclick="openTool(\'chrono\')"><div style="color:var(--et,var(--e));display:flex;justify-content:center">'+ICN('stopwatch',26)+'</div><div style="font-weight:700;font-size:13px;margin-top:6px">'+t('toolChronoName')+'</div></div><div class="card" style="flex:1;padding:14px;margin:0;cursor:pointer;text-align:center" onclick="openQuickTimer()"><div style="color:var(--warn);display:flex;justify-content:center">'+ICN('timer',26)+'</div><div style="font-weight:700;font-size:13px;margin-top:6px">'+t('quickTimer')+'</div></div></div>';
  h+='<div style="display:flex;gap:10px;align-items:center"><div class="searchbox" style="flex:1;min-width:0"><span class="searchic">'+ICN('search',18,'var(--muted)')+'</span><input class="inp" id="toolSearchInp" type="search" enterkeyhint="search" autocomplete="off" style="padding-left:42px" placeholder="'+t('searchTool')+'" value="'+escHtml(toolSearch||'')+'"></div></div>';
  return h+'<div id="toolRes">'+outilsList()+'</div>';
}
// Résultats de recherche, ou favoris + outils principaux + autres outils.
function outilsList(){
  let h='';
  const sansAccent=x=>String(x||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  const q=sansAccent(toolSearch).trim();
  if(q){
    const res=Object.entries(TOOLS).filter(([k,tl])=>sansAccent(tl.name+' '+tl.sub+' '+favShort(k)).includes(q));
    h+='<div class="lab" style="margin:14px 0 10px">'+tp('resultsCount',res.length)+'</div>';
    res.forEach(([k,tl])=>{ h+=toolRow(k,tl); });
    return h;
  }
  const rowHTML=k=>{ const tl=TOOLS[k]; return tl?'<div class="list-row" onclick="openTool(\''+k+'\')"><div class="lr-icon">'+tl.icon+'</div><div class="lr-txt"><div class="lr-title">'+tl.name+'</div><div class="lr-sub">'+tl.sub+'</div></div><span class="lr-chev">'+ICN('chevronR',16)+'</span></div>':''; };
  const tileHTML=k=>{ const tl=TOOLS[k]; return tl?'<div class="favtile" onclick="openTool(\''+k+'\')"><div style="color:var(--et,var(--e));display:flex;justify-content:center">'+tl.icon+'</div><div class="favlab">'+favShort(k)+'</div></div>':''; };
  // MODE SIMPLIFIÉ : pas de favoris à gérer ; les outils du quotidien en grandes lignes
  // (la prière comprise, sinon seulement joignable depuis l'Accueil), le reste en tuiles
  // de trois par ligne, plus lisibles que les quatre du mode normal.
  if(P.easyMode){
    const top=['aio','priere','convert','notes'];
    h+='<div class="lab" style="margin:20px 0 12px">'+t('mainTools')+'</div>'+top.map(rowHTML).join('');
    h+='<div class="lab" style="margin:22px 0 12px">'+t('otherTools')+'</div><div class="ez-toolgrid">'+OTHER_TOOLS.filter(k=>!top.includes(k)).map(tileHTML).join('')+'</div>';
    return h;
  }
  // FAVORIS
  const favs=toolFav().filter(k=>TOOLS[k]);
  h+='<div class="row" style="margin:18px 0 10px"><span class="lab">'+t('favorites')+'</span><span class="see" style="font-size:12px;color:var(--et,var(--e));cursor:pointer" onclick="editFavs()">'+t('edit')+'</span></div>';
  h+='<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-bottom:22px">';
  favs.slice(0,8).forEach(k=>{ const tl=TOOLS[k]; h+='<div class="favtile" onclick="openTool(\''+k+'\')"><div style="color:var(--et,var(--e));display:flex;justify-content:center">'+tl.icon+'</div><div class="favlab">'+favShort(k)+'</div></div>'; });
  h+='</div>';
  // OUTILS PRINCIPAUX
  h+='<div class="lab" style="margin:0 0 12px">'+t('mainTools')+'</div>';
  MAIN_TOOLS.forEach(k=>{ const tl=TOOLS[k];
    h+='<div class="list-row" onclick="openTool(\''+k+'\')"><div class="lr-icon">'+tl.icon+'</div><div class="lr-txt"><div class="lr-title">'+tl.name+'</div><div class="lr-sub">'+tl.sub+'</div></div><span class="lr-chev">'+ICN('chevronR',16)+'</span></div>';
  });
  // AUTRES OUTILS
  h+='<div class="lab" style="margin:18px 0 12px">'+t('otherTools')+'</div><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:9px">';
  OTHER_TOOLS.forEach(k=>{ const tl=TOOLS[k]; h+='<div class="favtile" style="padding:12px 4px" onclick="openTool(\''+k+'\')"><div style="color:var(--et,var(--e));display:flex;justify-content:center">'+tl.icon+'</div><div class="favlab">'+favShort(k)+'</div></div>'; });
  h+='</div>';
  return h;
}
// Labels courts pour les tuiles, par clé d'outil (indépendant de la langue affichée dans le nom complet)
function favShort(k){ const m={aio:{fr:'Perf. Lab',en:'Perf. Lab',ar:'مختبر'},sante:{fr:'Santé',en:'Health',ar:'الصحة'},chrono:{fr:'Chrono',en:'Timer',ar:'ساعة'},convert:{fr:'Convert.',en:'Convert.',ar:'تحويل'},vdot:{fr:'VDOT',en:'VDOT',ar:'VDOT'},bmr:{fr:'Calories',en:'Calories',ar:'سعرات'},hydra:{fr:'Eau',en:'Water',ar:'ماء'},
    // 18/09 : noms complets trop longs pour une tuile de grille (ex. "Ratio de
    // charge (ACWR)"). 'calories' (course) distingue volontairement de bmr
    // (deja "Calories" tout court) pour ne pas afficher 2 tuiles identiques.
    rm:{fr:'1RM',en:'1RM',ar:'1RM'},tonnage:{fr:'Tonnage',en:'Tonnage',ar:'الحمولة'},
    calories:{fr:'Calo. course',en:'Run calo.',ar:'سعرات الجري'},prog:{fr:'Progression',en:'Progress',ar:'التطور'},
    pomodoro:{fr:'Pomodoro',en:'Pomodoro',ar:'بومودورو'},load:{fr:'ACWR',en:'ACWR',ar:'ACWR'},repos:{fr:'Repos',en:'Rest',ar:'الراحة'}};
  return (m[k]&&m[k][curLang()])||(TOOLS[k]?TOOLS[k].name:k); }
function editFavs(){
  let h='<div class="tip" style="margin-bottom:14px">'+t('tapStarHint')+'</div>';
  Object.entries(TOOLS).forEach(([k,tl])=>{ h+=toolRow(k,tl); });
  $('#settingsBody').innerHTML=h; $('#ovSettings').querySelector('h2').textContent=t('editFavsTitle'); openOv('ovSettings');
}
function toolRow(k,tl){ const fav=toolFav().includes(k);
  return '<div class="list-row"><div class="lr-icon" style="cursor:pointer" onclick="openTool(\''+k+'\')">'+tl.icon+'</div><div class="lr-txt" style="cursor:pointer" onclick="openTool(\''+k+'\')"><div class="lr-title">'+tl.name+'</div>'+(tl.sub?'<div class="lr-sub">'+tl.sub+'</div>':'')+'</div><span onclick="event.stopPropagation();toggleFav(\''+k+'\')" title="'+t('favoriteLab')+'" style="color:'+(fav?'var(--or)':'var(--dim)')+';cursor:pointer;padding:4px;display:flex">'+ICN('star',17)+'</span></div>'; }
function openQuickTimer(){ outilsFrom='home'; outilsTab='_timer'; renderOutilsTimer(); }
function renderOutilsTimer(){ swapIn('s-outils','<div class="row" style="margin-bottom:14px"><button class="x" onclick="outilsTab=\'home\';renderOutils()">‹</button><div class="man" style="font-weight:800;font-size:17px;flex:1;text-align:center">'+t('quickTimer')+'</div><div style="width:34px"></div></div><div id="outBody"></div>'); renderTimer(); }

/* ============ TABLEAU DE BORD SANTÉ ============ */
function renderSanteTool(){ const sb=document.getElementById('santeBody'); if(sb){ sb.innerHTML=santeHTML(); return; } const o=$('#outBody'); if(o) o.innerHTML=santeHTML(); }
function santeHTML(){
  const w=P.weight||62, ht=P.height||175;
  const imc=w/Math.pow(ht/100,2);
  let imcCat,imcCol; if(imc<18.5){imcCat=t('imcUnderweight');imcCol='--warn';}else if(imc<25){imcCat=t('imcNormal');imcCol='--ok';}else if(imc<30){imcCat=t('imcOverweight');imcCol='--warn';}else{imcCat=t('imcObese');imcCol='--bad';}
  // dernier log santé / sommeil depuis SESSLOG (debriefs)
  const lastLog=SESSLOG[SESSLOG.length-1]||{};
  const ag=+age(), bmrAge=isFinite(ag)&&ag>0?ag:25;
  const bmr=Math.round((P.sex==='Femme')?(10*w+6.25*ht-5*bmrAge-161):(10*w+6.25*ht-5*bmrAge+5));
  const burned=SESS.slice(-7).reduce((a,s)=>a+(s.km||0)*0.9*w/1000*1000,0); // approx kcal 7j run
  const freq=runCountWeek()+muscuCountWeek();
  let h='';
  // POIDS
  const last=WEIGHTLOG[WEIGHTLOG.length-1], prev=WEIGHTLOG[WEIGHTLOG.length-2];
  const trend=last&&prev?(last.w-prev.w):0;
  h+='<div class="card"><div class="row"><div class="card-t" style="margin:0">'+t('weightLab')+'</div><span style="font-size:12px;color:var(--et,var(--e));cursor:pointer" onclick="addWeight()">'+t('addBtn')+'</span></div>';
  h+='<div class="row" style="align-items:flex-end;margin-top:8px"><div class="man" style="font-size:36px;font-weight:800">'+hKm(last?last.w:w)+'<span style="font-size:16px;color:var(--muted)"> kg</span></div>'+(trend?'<span class="num" style="margin-left:10px;color:'+(trend<0?'var(--ok)':'var(--warn)')+'">'+(trend>0?'▲ +':'▼ ')+fmt1(trend)+' kg</span>':'')+'</div>';
  if(WEIGHTLOG.length>=2) h+='<div style="margin-top:12px">'+weightSparkline()+'</div>';
  h+='</div>';
  // IMC
  h+='<div class="card"><div class="row"><div><div class="card-t" style="margin:0">'+t('imcLab')+'</div><div class="man" style="font-size:28px;font-weight:800;margin-top:6px;color:var('+imcCol+')">'+fmt1(imc)+'</div></div><div class="badge" style="background:color-mix(in srgb,var('+imcCol+') 10%,transparent);color:var('+imcCol+')">'+imcCat+'</div></div>'+
    '<div class="pbar" style="margin-top:12px"><div style="width:'+Math.min(100,(imc/40)*100)+'%;background:var('+imcCol+')"></div></div></div>';
  // INDICATEURS — grille
  h+='<div class="sgrid" style="margin-bottom:14px">';
  h+='<div class="sbox"><div class="v" style="color:var(--et,var(--e))">'+freq+'</div><div class="l">'+t('sessionsPerWeek')+'</div></div>';
  h+='<div class="sbox"><div class="v" style="color:var(--or)">'+bmr+'</div><div class="l">'+t('metabolismKcal')+'</div></div>';
  h+='<div class="sbox"><div class="v" style="color:var(--bad)">'+Math.round(burned)+'</div><div class="l">'+t('burned7d')+'</div></div>';
  h+='<div class="sbox"><div class="v" style="color:var(--platine)">'+hKm(Math.round(w*35/100)/10)+' L</div><div class="l">'+t('waterPerDay')+'</div></div>';
  h+='</div>';
  // SOMMEIL / FATIGUE / RÉCUP (depuis derniers debriefs)
  const recent=SESSLOG.slice(-7);
  if(recent.length){
    const avg=(f)=>recent.reduce((a,x)=>a+(x[f]||0),0)/recent.length;
    const sleep=avg('sleep'),fatigue=avg('fatigue'),feel=avg('feel');
    h+='<div class="card"><div class="card-t">'+t('recentFormTitle')+'</div>';
    h+=santeBar(t('sleepLab'),sleep,5,'--platine');
    h+=santeBar(t('energyFeelLab'),feel,5,'--ok');
    h+=santeBar(t('fatigueLab'),fatigue,5,'--warn');
    // conseil intelligent
    let tip=t('tipBalanced');
    if(fatigue>=4) tip=t('tipHighFatigue');
    else if(sleep<=2.5) tip=t('tipLowSleep');
    else if(feel>=4) tip=t('tipGreatFeel');
    h+='<div class="tip" style="margin-top:12px">'+tip+'</div></div>';
  } else {
    h+='<div class="card"><div class="empty"><div class="em-ic">'+ICN('clipboard',36,'currentColor')+'</div><div style="font-size:13px">'+t('noDebriefHint')+'</div></div></div>';
  }
  // NUTRITION (rappel macros indicatifs)
  const prot=Math.round(w*1.8), carbs=Math.round(w*5), lip=Math.round(w*1);
  h+='<div class="card"><div class="card-t">'+t('nutritionTitle')+'</div>';
  h+='<div class="sgrid"><div class="sbox"><div class="v" style="font-size:18px;color:var(--ok)">'+prot+'g</div><div class="l">'+t('proteinLab')+'</div></div><div class="sbox"><div class="v" style="font-size:18px;color:var(--or)">'+carbs+'g</div><div class="l">'+t('carbsLab')+'</div></div><div class="sbox"><div class="v" style="font-size:18px;color:var(--warn)">'+lip+'g</div><div class="l">'+t('fatLab')+'</div></div><div class="sbox"><div class="v" style="font-size:18px">'+Math.round(prot*4+carbs*4+lip*9)+'</div><div class="l">'+t('kcalTarget')+'</div></div></div></div>';
  return h;
}
function santeBar(label,val,max,col){ const pct=Math.min(100,val/max*100); const icN=['warning','close','target','check','star'][Math.max(0,Math.min(4,Math.round(val)-1))];
  const ic=val?ICN(icN,14):'';
  return '<div style="margin-bottom:10px"><div class="row" style="margin-bottom:4px"><span style="font-size:13px">'+label+'</span><span style="font-size:13px;display:inline-flex;align-items:center;gap:4px">'+(val?ic+' '+fmt1(val)+'/'+max:'—')+'</span></div><div class="pbar"><div style="width:'+pct+'%;background:var('+col+')"></div></div></div>'; }
function weightSparkline(){
  const data=WEIGHTLOG.slice(-14).map(x=>+(x&&x.w)).filter(Number.isFinite); if(data.length<2)return''; // une entrée importée mal formée ne casse plus le tracé
  const min=Math.min(...data),max=Math.max(...data),rng=(max-min)||1; const W=300,H=60;
  const pts=data.map((v,i)=>(i/(data.length-1)*W).toFixed(1)+','+(H-(v-min)/rng*H).toFixed(1)).join(' ');
  return '<svg viewBox="0 0 '+W+' '+H+'" style="width:100%;height:60px"><polyline points="'+pts+'" fill="none" stroke="var(--e)" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
}
function addWeight(){ const cur=P.weight||62; const whole=Math.floor(cur),dec=Math.round((cur-whole)*10);
  openPicker({title:t('weightPickerTitle'),cols:[{values:range(30,200),sel:Math.max(0,whole-30)},{values:range(0,9),sel:dec,unit:'kg'}],seps:['.'],onOk:idx=>{ const w=(idx[0]+30)+idx[1]/10; WEIGHTLOG.push({date:todayKey(),w}); P.weight=w; saveAll(); renderSanteTool(); toast(t('weightSaved')); }}); }

/* ============ PERFORMANCE LAB — calculateur intelligent ============ */
/* 4 valeurs : distance (km), time (s), pace (s/km), speed (km/h).
   L'utilisateur saisit 2 valeurs → les 2 autres se calculent.
   On mémorise l'ordre des saisies (recent[]) pour savoir lesquelles fixer. */
let LAB={dist:null,time:null,pace:null,speed:null,recent:[]};
function labSet(field,val){
  LAB[field]=val;
  LAB.recent=[field,...LAB.recent.filter(f=>f!==field)].slice(0,2);
  computeLab();
  renderAIO();
}
function computeLab(){
  const r=LAB.recent;
  if(r.length<2) return;
  const has=f=>LAB[f]!=null&&!isNaN(LAB[f])&&LAB[f]>0;
  const [a,b]=r;
  const set2=new Set([a,b]);
  // pace <-> speed sont liés : si l'un est saisi, dérive l'autre
  if(has('pace')&&!set2.has('speed')) LAB.speed=3600/LAB.pace;
  if(has('speed')&&!set2.has('pace')) LAB.pace=3600/LAB.speed;
  // Résoudre selon les 2 connus
  if(set2.has('dist')&&set2.has('time')&&has('dist')&&has('time')){ LAB.pace=LAB.time/LAB.dist; LAB.speed=3600/LAB.pace; }
  else if(set2.has('dist')&&set2.has('pace')&&has('dist')&&has('pace')){ LAB.time=LAB.pace*LAB.dist; LAB.speed=3600/LAB.pace; }
  else if(set2.has('dist')&&set2.has('speed')&&has('dist')&&has('speed')){ LAB.pace=3600/LAB.speed; LAB.time=LAB.pace*LAB.dist; }
  else if(set2.has('time')&&set2.has('pace')&&has('time')&&has('pace')){ LAB.dist=LAB.time/LAB.pace; LAB.speed=3600/LAB.pace; }
  else if(set2.has('time')&&set2.has('speed')&&has('time')&&has('speed')){ LAB.pace=3600/LAB.speed; LAB.dist=LAB.time/LAB.pace; }
}
function renderAIO(){
  const computed=f=>LAB.recent.length>=2 && !LAB.recent.includes(f) && LAB[f]!=null;
  let h='<div class="tip" style="margin-bottom:16px">'+t('labHint')+'</div>';
  h+=labField(t('distField'),'','dist',LAB.dist!=null?fmtN(LAB.dist,2)+' km':'—',computed('dist'));
  h+=labField(t('timeField'),'','time',LAB.time!=null?fmtTime(LAB.time):'—',computed('time'));
  h+=labField(t('paceField'),'','pace',LAB.pace!=null?spkToStr(LAB.pace)+' /km':'—',computed('pace'));
  h+=labField(t('speedField'),'','speed',LAB.speed!=null?fmtN(LAB.speed,2)+' km/h':'—',computed('speed'));
  h+='<button class="btn ghost" style="margin-top:10px" onclick="resetLab()">'+t('resetBtn')+'</button>';
  // Bonus : splits + prédictions si distance & pace connus
  if(LAB.dist&&LAB.pace&&LAB.dist>=1){
    h+='<div class="card-t" style="margin-top:20px">'+t('splitTimesTitle')+'</div>';
    const n=Math.min(Math.floor(LAB.dist),42);
    for(let k=1;k<=n;k++){ const hi=[5,10,21,42].includes(k); h+='<div class="zrow" style="padding:9px 0"><span class="zname" style="'+(hi?'color:var(--et,var(--e))':'')+'">km '+k+(hi?'':'')+'</span><span class="zval mono">'+fmtTime(LAB.pace*k)+'</span></div>'; }
    if(LAB.dist%1>0.01) h+='<div class="zrow" style="padding:9px 0"><span class="zname">'+fmtN(LAB.dist,2)+' km</span><span class="zval mono">'+fmtTime(LAB.time)+'</span></div>';
  }
  $('#outBody').innerHTML=h;
}
function labField(label,icon,field,val,isComputed){
  const filled=LAB[field]!=null;
  return '<div class="card" style="padding:14px;margin-bottom:9px;cursor:pointer;'+(isComputed?'border-color:var(--e);background:var(--ed)':'')+'" onclick="editLab(\''+field+'\')"><div class="row"><div class="row" style="gap:11px"><span style="font-size:19px">'+icon+'</span><div><div style="font-size:11px;color:var(--muted)">'+label+(isComputed?' · '+t('calculatedLab'):filled?'':' · '+t('toFillLab'))+'</div><div class="mono" style="font-weight:700;font-size:19px;margin-top:2px;color:'+(isComputed?'var(--et,var(--e))':'var(--snow)')+'">'+val+'</div></div></div><span style="color:var(--dim);font-size:15px">'+(isComputed?'':'')+'</span></div></div>';
}
function editLab(field){
  if(field==='dist') pickDistance(t('distField'),LAB.dist||10,v=>labSet('dist',v));
  else if(field==='time') pickTime(t('timeField'),LAB.time||1800,v=>labSet('time',v));
  else if(field==='pace') pickPace(t('paceField'),LAB.pace||270,v=>labSet('pace',v));
  else if(field==='speed') pickSpeed(t('speedField'),LAB.speed||12,v=>labSet('speed',v));
}
function resetLab(){ LAB={dist:null,time:null,pace:null,speed:null,recent:[]}; renderAIO(); }

/* ----- Nouveaux outils ----- */
function renderVDOTtool(){
  const vdot=getUserVDOT();
  let h='<div class="card" style="text-align:center"><div class="man" style="font-size:48px;font-weight:800;color:var(--et,var(--e))">'+(vdot?fmt1(vdot):'—')+'</div><div class="lab">'+t('vdotToolTitle')+'</div></div>';
  if(vdot){ const vo2=fmt1(vdot);
    h+='<div class="card"><div class="card-t">'+t('physioEstimates')+'</div>'+
      '<div class="zrow"><span class="zname">'+t('vo2maxEst')+'</span><span class="zval">'+vo2+' ml/kg/min</span></div>'+
      '<div class="zrow"><span class="zname">'+t('thresholdPace')+'</span><span class="zval mono">'+spkToStr(paceFromPct(vdot,.88))+'/km</span></div>'+
      // Allures de COURSE prédites (même calcul que le Jour J et les prédictions des
      // Stats). Avant : 80 % / 83,5 % de vVO2max, soit 4:48/km au marathon pour un
      // VDOT 50 alors que la prédiction du même VDOT donne 4:31/km (audit 27/09).
      '<div class="zrow"><span class="zname">'+t('marathonPace')+'</span><span class="zval mono">'+spkToStr(predictTime(vdot,42195)/42.195)+'/km</span></div>'+
      '<div class="zrow"><span class="zname">'+t('halfPace')+'</span><span class="zval mono">'+spkToStr(predictTime(vdot,21097.5)/21.0975)+'/km</span></div>'+
      '<div class="zrow"><span class="zname">'+t('efPace')+'</span><span class="zval mono">'+spkToStr(paceFromPct(vdot,.70))+'/km</span></div></div>';
  }
  h+='<div class="tip">'+t('vdotAutoTip')+'</div>';
  $('#outBody').innerHTML=h;
}
let rmW=80,rmR=5;
function renderRMtool(){
  const rm=rmR<=1?rmW:Math.round(rmW*(1+rmR/30)); // Epley (1 rép. = la charge elle-même, pas +3 %)
  let h='<div class="card"><div class="field"><label>'+t('liftedLoadKgLab')+'</label><div class="stepper"><button onclick="rmW=Math.max(0,rmW-2.5);renderRMtool()">−</button><span class="val">'+rmW+'</span><button onclick="rmW+=2.5;renderRMtool()">+</button></div></div>';
  h+='<div class="field"><label>'+t('repsLab')+'</label><div class="stepper"><button onclick="rmR=Math.max(1,rmR-1);renderRMtool()">−</button><span class="val">'+rmR+'</span><button onclick="rmR++;renderRMtool()">+</button></div></div></div>';
  h+='<div class="card" style="text-align:center"><div class="man" style="font-size:42px;font-weight:800;color:var(--et,var(--e))">'+rm+' kg</div><div class="lab">'+t('estimated1RMLab')+'</div></div>';
  h+='<div class="card"><div class="card-t">'+t('percentOf1RMLab')+'</div>'+[[95,2],[90,4],[85,6],[80,8],[75,10],[70,12],[60,15]].map(x=>'<div class="zrow"><span class="zname">'+x[0]+'% · ~'+x[1]+' '+t('repsShort')+'</span><span class="zval">'+Math.round(rm*x[0]/100)+' kg</span></div>').join('')+'</div>';
  $('#outBody').innerHTML=h;
}
