  newyear:{every:[5000,10000],acts:['fireworks'],l:()=>'',r:()=>''},
  halloween:{every:[6000,12000],acts:['spiderDrop','spiderDrop','spiderRun','bats','ghost','eyes'],
    l:()=>fxIt(FX_ART.pumpkin(),46)+fxIt(FX_ART.pumpkin(),30),r:()=>fxIt(FX_ART.pumpkin(),40)}
