/* ---------- ÎLOT D'ACTIVITÉ (V3.4.0) ----------
   Une séance, un repos, un chrono, un minuteur ou un Pomodoro en cours restent visibles
   partout, dans une capsule posée au-dessus de la barre du bas : on continue d'utiliser
   l'app pendant qu'ils tournent. Deux activités à la fois : la plus urgente occupe la
   capsule, l'autre une bulle à côté (comme l'îlot de l'iPhone). Toucher la capsule ramène
   à l'écran de l'activité ; ses boutons agissent sur place (pause, +30 s, passer).
   Une activité n'y figure pas quand son propre écran est déjà affiché.
   (Une vraie « Live Activity » sur l'écran verrouillé reste réservée aux apps natives :
   voir showBgActivityNotif, qui garde sa notification au démarrage.) */
function ikFmtClock(ms){ const d=new Date(ms); return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0'); }
function liveNextExName(){
  if(!LIVE||!LIVE.state) return '';
  const i=LIVE.state.findIndex(st=>st.sets.some(x=>!x));
  return i>=0 && LIVE.prog.ex[i] ? LIVE.prog.ex[i].name : '';
}
function ikScrIs(tab){ return document.body.dataset.scr==='outils' && outilsTab===tab; }
function ikActivities(){
  const now=Date.now(), out=[];
  if(_rest){
    const left=Math.max(0,(_rest.endAt+_rest.extra*1000-now)/1000), tot=_rest.total+_rest.extra, nx=liveNextExName();
    out.push({k:'rest',icon:'pause',title:t('restTitle'),sub:nx?tp('islandNext',nx):'',time:fmtMS(Math.ceil(left)),f:tot?left/tot:0,
      c:left<=5?'var(--warn)':'var(--e2)',urgent:left>0&&left<=5,acts:'rest',
      mine:()=>{ const o=$('#restOv'); return !!(o&&o.classList.contains('on')); }});
  }
  const tLeft=timer.running&&timer.endAt?Math.max(0,Math.ceil((timer.endAt-now)/1000)):timer.left;
  if(timer.running || (tLeft>0 && tLeft<timer.total)){
    const pct=timer.total?tLeft/timer.total:0;
    out.push({k:'timer',icon:'timer',title:t('quickTimer'),sub:timer.running?tp('islandEndsAt',ikFmtClock(timer.endAt)):t('islandPaused'),
      time:fmtMS(tLeft),f:pct,c:pct>.5?'var(--e)':pct>.2?'var(--warn)':'var(--bad)',urgent:timer.running&&tLeft<=10,acts:'toggle',on:timer.running,
      mine:()=>ikScrIs('_timer')});
  }
  const pLen=pomoLen(pomoState.phase), pLeft=pomoState.running&&pomoState.endAt?Math.max(0,Math.ceil((pomoState.endAt-now)/1000)):pomoState.left;
  if(pomoState.running || (pLeft>0 && pLeft<pLen)){
    const work=pomoState.phase==='work';
    out.push({k:'pomo',icon:work?'brain':'coffee',title:work?t('pomoFocus'):t('pomoBreak'),sub:pomoState.running?tp('islandEndsAt',ikFmtClock(pomoState.endAt)):t('islandPaused'),
      time:fmtMS(pLeft),f:pLen?pLeft/pLen:0,c:work?'var(--bad)':'var(--ok)',acts:'toggle',on:pomoState.running,mine:()=>ikScrIs('pomodoro')});
  }
  if(LIVE && !_finishingLive && LIVE.prog){
    const tot=LIVE.prog.ex.reduce((a,x)=>a+(x.sets||0),0);
    out.push({k:'live',icon:'dumbbell',title:LIVE.prog.name,sub:tp('islandSets',LIVE.setsDone,tot),time:fmtTime((now-LIVE.start)/1000),
      f:tot?LIVE.setsDone/tot:0,c:'var(--e)',acts:'open',live:true,
      mine:()=>{ const o=$('#ovLive'); return !!(o&&o.classList.contains('on')); }});
  }
  const cTot=chrono.elapsed+(chrono.running?now-chrono.start:0);
  if(chrono.running || cTot>0){
    out.push({k:'chrono',icon:'stopwatch',title:t('toolChronoName'),sub:chrono.laps.length?t('lapBtn')+' '+(chrono.laps.length+1):(chrono.running?'':t('islandPaused')),
      time:fmtChrono(cTot).slice(0,-1),f:(cTot%60000)/60000,c:'var(--e)',acts:'toggle',on:chrono.running,live:chrono.running,mine:()=>ikScrIs('chrono')});
  }
  return out;
}
function ikIslandOpen(k){
  if(k==='live') return expandLive();
  if(k==='rest'){ if(LIVE && !$('#ovLive').classList.contains('on')) expandLive(); return expandRest(); }
  if(k==='timer'){ nav('outils'); openQuickTimer(); }
  else if(k==='pomo'){ nav('outils'); openTool('pomodoro'); }
  else if(k==='chrono'){ nav('outils'); openTool('chrono'); }
  ikIslandKick();
}
function ikIslandAct(k,a){
  if(a==='add') addRest(30);
  else if(a==='skip') skipRest();
  else if(a==='toggle'){ if(k==='timer') timerToggle(); else if(k==='pomo') pomoToggle(); else if(k==='chrono') chronoToggle(); }
  else if(a==='reset'){ if(k==='timer') resetTimer(); else if(k==='pomo') pomoReset(); else if(k==='chrono') chronoReset(); }
  try{ if(navigator.vibrate) navigator.vibrate(8); }catch(e){}
  ikIslandKick();
}
let _iki=null, _ikiT=0, _ikiFlash=null;
const IKI_C=2*Math.PI*16;
function ikRingSVG(){ return '<svg viewBox="0 0 40 40" aria-hidden="true"><circle class="isl-trk" cx="20" cy="20" r="16"/><circle class="isl-arc" cx="20" cy="20" r="16" stroke-dasharray="'+IKI_C.toFixed(2)+'" stroke-dashoffset="0"/></svg>'; }
function ikIslandEl(){
  if(_iki) return _iki;
  const el=document.createElement('div'); el.id='ikIsland'; el.setAttribute('role','group');
  el.innerHTML='<div class="isl-drag"><button type="button" class="isl-mini"><span class="isl-ring">'+ikRingSVG()+'<i class="isl-ic"></i></span><span class="isl-mt mono"></span></button>'+
    '<div class="isl-main" role="button" tabindex="0"><span class="isl-ring">'+ikRingSVG()+'<i class="isl-ic"></i></span>'+
    '<span class="isl-txt"><b class="isl-t"></b><span class="isl-s"></span></span><span class="isl-time mono"></span><span class="isl-acts"></span>'+
    '<span class="isl-flash"></span></div></div>';
  document.body.appendChild(el); // après #nav : sa position suit la barre (voir #nav.nav-hidden ~ #ikIsland)
  islApplyPos(el,islSavedPos());
  el.addEventListener('click',e=>{
    if(el._dragged){ el._dragged=false; e.stopPropagation(); return; } // la fin d'un glisser n'est pas un toucher
    const b=e.target.closest('[data-act]');
    if(b){ e.stopPropagation(); return ikIslandAct(b.dataset.k,b.dataset.act); }
    // rangé en bulle : un toucher le redéplie (en haut ou en bas, selon où il est rangé)
    if(el.classList.contains('bub')){ islMoveTo(/^t/.test(el.dataset.pos)?'top':'bottom'); return; }
    if(e.target.closest('.isl-mini')){ if(el._mini) ikIslandOpen(el._mini.k); return; }
    if(e.target.closest('.isl-main') && el._main) ikIslandOpen(el._main.k);
  });
  islBindDrag(el);
  el.addEventListener('keydown',e=>{ if((e.key==='Enter'||e.key===' ') && e.target.classList.contains('isl-main') && el._main){ e.preventDefault(); ikIslandOpen(el._main.k); } });
  _iki={el,main:el.querySelector('.isl-main'),mini:el.querySelector('.isl-mini')};
  return _iki;
}
function ikIslandBlocked(){
  return !!(document.querySelector('#login.on,#ob.on,#ikIntro,#alarmOv') || (typeof _tourOn!=='undefined' && _tourOn));
}
function ikIslandFill(box,a,full){
  const arc=box.querySelector('.isl-arc'), ic=box.querySelector('.isl-ic');
  if(box._k!==a.k || box._icon!==a.icon){ ic.innerHTML=ICN(a.icon,full?17:19); box._icon=a.icon; }
  box.style.setProperty('--isl-c',a.c);
  arc.setAttribute('stroke-dashoffset',(IKI_C*(1-Math.max(0,Math.min(1,a.f)))).toFixed(2));
  box.classList.toggle('urgent',!!a.urgent); box.classList.toggle('live',!!a.live);
  if(!full){ box.setAttribute('aria-label',a.title+' · '+a.time); box._k=a.k; return; }
  const tt=box.querySelector('.isl-t'), ss=box.querySelector('.isl-s'), tm=box.querySelector('.isl-time'), ac=box.querySelector('.isl-acts');
  if(tt.textContent!==a.title) tt.textContent=a.title;
  if(ss.textContent!==a.sub) ss.textContent=a.sub;
  if(tm.textContent!==a.time) tm.textContent=a.time;
  const sig=a.k+'|'+a.acts+'|'+(a.on?1:0);
  if(ac._sig!==sig){
    ac._sig=sig;
    const btn=(act,inner,lab)=>'<button type="button" class="isl-b" data-k="'+a.k+'" data-act="'+act+'" aria-label="'+lab+'">'+inner+'</button>';
    ac.innerHTML=a.acts==='rest'? btn('add','<span dir="ltr">+30</span>',t('add30sLab'))+btn('skip',ICN('skip',16),t('skipLab'))
      : a.acts==='toggle'? (a.on?'':btn('reset',ICN('close',15),t('resetBtn2')))+btn('toggle',ICN(a.on?'pause':'play',16),a.on?t('pauseShort'):t('playLab'))
      : '<span class="isl-go" aria-hidden="true">'+ICN('chevronU',18)+'</span>';
  }
  box.setAttribute('aria-label',a.title+' · '+a.time+(a.sub?' · '+a.sub:''));
  if(box._k && box._k!==a.k && !ikMotionOff()){ box.classList.remove('morph'); void box.offsetWidth; box.classList.add('morph'); }
  box._k=a.k;
}
function ikIslandFlash(msg,c){ _ikiFlash={msg,c:c||'var(--ok)',until:Date.now()+2600}; ikIslandKick(); }
function ikIslandKick(){ clearTimeout(_ikiT); _ikiT=setTimeout(ikIslandTick,0); }
function ikIslandTick(){
  _ikiT=0;
  const I=ikIslandEl(), el=I.el, now=Date.now();
  const acts=ikActivities();
  const flash=_ikiFlash && now<_ikiFlash.until ? _ikiFlash : null; if(!flash) _ikiFlash=null;
  const vis=ikIslandBlocked()?[]:acts.filter(a=>!a.mine());
  const show=vis.length>0 || (flash && !ikIslandBlocked());
  if(el.classList.contains('on')!==!!show){
    el.classList.toggle('on',!!show); document.body.classList.toggle('isl-on',!!show);
    if(show){ const n=document.getElementById('nav'); if(n) el.style.setProperty('--isl-nav',n.offsetHeight+'px'); }
  }
  if(show){
    const main=vis[0], mini=vis[1];
    I.main.classList.toggle('flash',!!flash);
    if(main) ikIslandFill(I.main,main,true);
    if(flash){ const f=I.main.querySelector('.isl-flash'); f.textContent=flash.msg; I.main.style.setProperty('--isl-c',flash.c); }
    el._main=main||null; el._mini=mini||null;
    const bub=el.classList.contains('bub');
    el.classList.toggle('duo',!!mini && !bub);
    // en bulle, c'est l'activité principale qui s'y montre, avec son temps
    if(bub && main){ ikIslandFill(I.mini,main,false); const mt=I.mini.querySelector('.isl-mt'); if(mt.textContent!==main.time) mt.textContent=main.time; }
    else if(mini) ikIslandFill(I.mini,mini,false);
  }
  if(acts.length || flash){
    const fast=show && vis[0] && vis[0].k==='chrono' && chrono.running;
    _ikiT=setTimeout(ikIslandTick, fast?100:(show?250:400));
  }
}
/* ÎLOT QUI SE DÉPLACE (V3.5.0) — à la façon IKORUN : on l'attrape et on le lance.
   · vers le bas : il se range en bulle dans le coin (celui du côté où part le doigt) ;
   · vers le haut : il devient une capsule en haut de l'écran, sous l'heure ;
   · vers un bord : il s'accroche en bulle au coin le plus proche ;
   · une bulle touchée se redéplie ; lancée vers le milieu, elle redevient capsule.
   La goutte suit le doigt en s'étirant, puis rebondit à sa place (animation FLIP : on
   mesure avant/après et on anime l'écart). La place choisie est retenue sur l'appareil. */
const ISL_POS=['bottom','top','bl','br','tl','tr'];
function islSavedPos(){ try{ const p=localStorage.getItem('ik_isl_pos'); return ISL_POS.includes(p)?p:'bottom'; }catch(e){ return 'bottom'; } }
function islApplyPos(el,pos){
  el.dataset.pos=pos; el.classList.toggle('bub',pos.length===2);
  document.body.classList.toggle('isl-low',pos==='bottom'); // seule la capsule du bas réserve de la place
}
function islMoveTo(pos,fromRect){
  const I=ikIslandEl(), el=I.el, d=el.querySelector('.isl-drag');
  const from=fromRect||d.getBoundingClientRect();
  el.style.transition='none';
  islApplyPos(el,pos); try{ localStorage.setItem('ik_isl_pos',pos); }catch(e){}
  clearTimeout(_ikiT); ikIslandTick(); // contenu à jour (bulle ↔ capsule) avant de mesurer
  const to=d.getBoundingClientRect(), k=uiRectFactor();
  const dx=((from.left+from.width/2)-(to.left+to.width/2))/k, dy=((from.top+from.height/2)-(to.top+to.height/2))/k;
  d.style.transition='none'; d.style.transform='translate('+dx.toFixed(1)+'px,'+dy.toFixed(1)+'px)';
  void d.offsetWidth; el.style.transition='';
  if(ikMotionOff()){ d.style.transform=''; }
  else { d.style.transition='transform .55s cubic-bezier(.3,1.35,.45,1)'; d.style.transform=''; clearTimeout(d._t); d._t=setTimeout(()=>{ d.style.transition=''; },580); }
  try{ if(navigator.vibrate) navigator.vibrate(10); }catch(e){}
}
function islBindDrag(el){
  const d=el.querySelector('.isl-drag'); let st=null;
  el.addEventListener('pointerdown',e=>{
    if(e.target.closest('[data-act]') || (e.pointerType==='mouse' && e.button!==0)) return;
    st={x:e.clientX,y:e.clientY,id:e.pointerId,on:false,lx:e.clientX,ly:e.clientY,lt:performance.now(),vx:0,vy:0};
  });
  el.addEventListener('pointermove',e=>{
    if(!st || e.pointerId!==st.id) return;
    const dx=e.clientX-st.x, dy=e.clientY-st.y;
    if(!st.on){ if(Math.hypot(dx,dy)<8) return; st.on=true; el.classList.add('dragging'); try{ el.setPointerCapture(e.pointerId); }catch(err){} }
    const now=performance.now(), dt=Math.max(1,now-st.lt);
    st.vx=(e.clientX-st.lx)/dt; st.vy=(e.clientY-st.ly)/dt; st.lx=e.clientX; st.ly=e.clientY; st.lt=now;
    // la goutte s'étire dans le sens du mouvement
    const z=uiZoomFactor(), sp=Math.min(1,Math.hypot(st.vx,st.vy)/2.2), ax=Math.abs(st.vx)>Math.abs(st.vy);
    d.style.transition='none';
    d.style.transform='translate('+(dx/z).toFixed(1)+'px,'+(dy/z).toFixed(1)+'px) scale('+(ax?1+sp*.08:1-sp*.05).toFixed(3)+','+(ax?1-sp*.05:1+sp*.08).toFixed(3)+')';
  });
  const fin=e=>{
    if(!st || e.pointerId!==st.id) return; const s=st; st=null;
    if(!s.on) return;
    el.classList.remove('dragging'); el._dragged=true; setTimeout(()=>{ el._dragged=false; },350);
    const vw=innerWidth, vh=innerHeight, fx=e.clientX, fy=e.clientY, dx=fx-s.x, dy=fy-s.y, pos=el.dataset.pos||'bottom';
    const side=fx<vw/2?'l':'r', half=fy<vh/2?'t':'b';
    let to=pos;
    if(pos==='bottom'||pos==='top'){
      if(Math.abs(dx)>vw*.28 || Math.abs(s.vx)>1.1) to=half+(dx<0?'l':'r');
      else if(pos==='bottom' && (dy>55 || s.vy>.7)) to='b'+side;
      else if(pos==='bottom' && (fy<vh*.38 || s.vy<-.9)) to='top';
      else if(pos==='top' && (dy<-40 || s.vy<-.7)) to='t'+side;
      else if(pos==='top' && (fy>vh*.62 || s.vy>.9)) to='bottom';
    } else {
      if(Math.abs(fx-vw/2)<vw*.18) to=fy<vh/2?'top':'bottom';
      else to=half+side;
    }
    islMoveTo(to,d.getBoundingClientRect());
  };
  el.addEventListener('pointerup',fin); el.addEventListener('pointercancel',fin);
}
// La séance se réduit dans l'îlot (bouton ⌄, glisser la fenêtre vers le bas, toucher le fond)
// sans jamais passer par closeOv('ovLive'), qui arrête ses minuteurs.
function minimizeLive(){
  if(!LIVE) return;
  const ov=$('#ovLive'); if(ov && ov.classList.contains('on')){ ovLeave(ov); ov.classList.remove('on'); ov.style.zIndex=''; }
  minimizeRest();
  ikIslandKick();
}
function expandLive(){ if(!LIVE) return; renderLive(); openOv('ovLive'); ikIslandKick(); }
function minimizeRest(){ const r=$('#restOv'); if(r && r.classList.contains('on')){ ovLeave(r); r.classList.remove('on'); } ikIslandKick(); }
function expandRest(){ const r=$('#restOv'); if(r){ clearTimeout(r._leaveT); r.classList.remove('ov-leaving'); const c=r.querySelector('.ov-card'); if(c) c.style.transform=''; r.style.zIndex=topZ(); r.classList.add('on'); } ikIslandKick(); }
// Barre du bas masquée au défilement : l'îlot descend prendre sa place.
if('ResizeObserver' in window){ const n=document.getElementById('nav'); if(n) new ResizeObserver(()=>{ if(_iki) _iki.el.style.setProperty('--isl-nav',n.offsetHeight+'px'); }).observe(n); }

/* ---------- AGENDA ---------- */
function renderAgenda(){
  let h='<button class="btn" style="margin-bottom:14px" onclick="addEvent()">'+t('addEventBtn')+'</button>';
  const evts=[...AGENDA].sort((a,b)=>new Date(a.date)-new Date(b.date));
  if(P.compDate) evts.unshift({date:P.compDate,title:''+(P.goal||t('competitionDefault')),fixed:true});
  if(!evts.length) h+='<div class="card"><div class="empty"><div class="em-ic">'+ICN('calendar',36,'currentColor')+'</div><div style="font-size:13px">'+t('noEventLab')+'</div></div></div>';
  else evts.forEach((e,i)=>{
    const dd=daysBetween(new Date(),new Date(e.date));
    h+='<div class="card"><div class="row"><div><div style="font-weight:700">'+escHtml(e.title)+'</div><div style="font-size:12px;color:var(--muted);margin-top:2px">'+fmtDate(e.date)+' · '+(dd>=0?'J-'+dd:t('pastLab'))+'</div></div>'+(e.fixed?'':'<button class="x" onclick="delEvent('+(i-(P.compDate?1:0))+')">'+ICN('trash',16)+'</button>')+'</div></div>';
  });
  $('#outBody').innerHTML=h;
}
function addEvent(){
  customPrompt(t('eventTitlePrompt'),'',ti=>{
    // Deuxième étape enchaînée : le champ date utilise le sélecteur natif du
    // téléphone (type="date"), plus fiable qu'une saisie libre au format AAAA-MM-JJ.
    customPrompt(t('eventDatePrompt'),todayKey(),d=>{
      AGENDA.push({title:ti.slice(0,80),date:d}); saveAll(); renderAgenda(); toast(t('eventAdded'));
    },{type:'date'});
  },{maxLength:80});
}
function delEvent(i){ AGENDA.splice(i,1); saveAll(); renderAgenda(); }

/* ---------- PRIÈRES (Béjaïa, UOIF) ---------- */
function renderPriere(){
  const times=prayerTimes();
  const now=new Date(); const nowMin=algeriaNowMin();
  const order=['Fajr','Dhuhr','Asr','Maghrib','Isha'];
  let activeIdx=-1;
  order.forEach((p,i)=>{ const[hh,mm]=times[p].split(':').map(Number); if(hh*60+mm<=nowMin) activeIdx=i; });
  let h='<div class="card"><div class="card-t">'+t('prayerTitle')+'</div><div style="font-size:12px;color:var(--muted);margin-bottom:14px">'+tp('uoifMethod',ikDate(now,'{weekday:long,day:numeric,month:long}',{weekday:'long',day:'numeric',month:'long'}))+'</div>';
  const icons={Fajr:'sun',Dhuhr:'sun',Asr:'sun',Maghrib:'moon',Isha:'moon'};
  order.forEach((p,i)=>{
    const act=i===activeIdx;
    h+='<div class="zrow" style="'+(act?'background:var(--ed);border-radius:12px;padding:11px 12px;margin:0 -4px':'')+'"><span style="display:inline-flex">'+ICN(icons[p],18)+'</span><span class="zname" style="margin-left:8px;'+(act?'color:var(--et,var(--e))':'')+'">'+trPrayer(p)+'</span><span class="zval mono" style="'+(act?'color:var(--et,var(--e));font-weight:700':'')+'">'+times[p]+'</span></div>';
  });
  h+='</div>';
  $('#outBody').innerHTML=h;
}
// Heures de prière de la ville choisie pour la météo (sinon Béjaïa), au jour de l'Algérie.
// Les notifications de prière envoyées par le serveur (send-prayer-notifs) restent calculées
// pour Béjaïa : le serveur ne connaît pas la ville (elle reste sur le téléphone).
function prayerTimes(){
  const loc=(typeof wxLocOrDefault==='function')?wxLocOrDefault():{lat:36.75,lon:5.07};
  const n=new Date(Date.now()+3600*1000), k=n.getUTCFullYear()+'-'+String(n.getUTCMonth()+1).padStart(2,'0')+'-'+String(n.getUTCDate()).padStart(2,'0');
  return prayerTimesFor(k,loc.lat,loc.lon,1);
}
function prayerTimesFor(dayKey,lat,lon,tz){
  // Béjaïa, méthode Fajr 18° / Isha 17°, fuseau Algérie fixe UTC+1.
  // AUDIT 24/09 : q (longitude moyenne du Soleil) et l'ascension droite n'étaient
  // jamais ramenés à [0,360[ / [0,24[ : dès fin mars, l'équation du temps dérivait
  // d'un ou plusieurs jours entiers et TOUTES les heures sortaient négatives
  // (« Fajr -19:03 · dans -44 min »). Même formule côté serveur
  // (send-prayer-notifs), où aucune notification de prière ne partait plus.
  // V3.5.0 : le jour et l'heure pris en compte sont ceux de l'Algérie, comme côté serveur
  // (send-prayer-notifs) — plus ceux de l'horloge du téléphone, qui décalait tout d'une
  // heure sur un téléphone réglé sur un autre fuseau (voyage, réglage manuel).
  const now=new Date(dayKey+'T12:00:00Z');
  const rad=Math.PI/180, fixA=a=>((a%360)+360)%360, fixH=h=>((h%24)+24)%24;
  const D=(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate(),12)-Date.UTC(2000,0,1,12))/86400000; // jours depuis J2000
  const g=fixA(357.529+0.98560028*D)*rad;
  const q=fixA(280.459+0.98564736*D);
  const L=fixA(q+1.915*Math.sin(g)+0.020*Math.sin(2*g))*rad;
  const e=(23.439-0.00000036*D)*rad;
  const decl=Math.asin(Math.sin(e)*Math.sin(L));
  const RA=fixH(Math.atan2(Math.cos(e)*Math.sin(L),Math.cos(L))/rad/15);
  let eqt=q/15-RA; if(eqt>12) eqt-=24; if(eqt<-12) eqt+=24;
  const Dhuhr=fixH(12+tz-lon/15-eqt);
  function hourAngle(angle){ const c=(Math.sin(-angle*rad)-Math.sin(lat*rad)*Math.sin(decl))/(Math.cos(lat*rad)*Math.cos(decl)); return Math.acos(Math.max(-1,Math.min(1,c)))/rad/15; }
  function asrAngle(){ const c=(Math.sin(Math.atan(1/(1+Math.tan(Math.abs(lat*rad-decl)))))-Math.sin(lat*rad)*Math.sin(decl))/(Math.cos(lat*rad)*Math.cos(decl)); return Math.acos(Math.max(-1,Math.min(1,c)))/rad/15; }
  const f=t=>{ t=fixH(t); let hh=Math.floor(t),mm=Math.round((t-hh)*60); if(mm===60){hh=(hh+1)%24;mm=0;} return String(hh).padStart(2,'0')+':'+String(mm).padStart(2,'0'); };
  return {Fajr:f(Dhuhr-hourAngle(18)),Sunrise:f(Dhuhr-hourAngle(0.833)),Dhuhr:f(Dhuhr+1/60),Asr:f(Dhuhr+asrAngle()),Maghrib:f(Dhuhr+hourAngle(0.833)),Isha:f(Dhuhr+hourAngle(17))};
}
// Prochaine prière à venir (bascule sur le Fajr du lendemain une fois Isha passée) —
// utilisé pour la mise en avant sur l'accueil (homePrayerCardHTML).
// Minutes écoulées depuis minuit, heure de l'Algérie (UTC+1 toute l'année).
function algeriaNowMin(){ const a=new Date(Date.now()+3600*1000); return a.getUTCHours()*60+a.getUTCMinutes(); }
function nextPrayerInfo(){
  const times=prayerTimes();
  const nowMin=algeriaNowMin();
  for(const p of ['Fajr','Dhuhr','Asr','Maghrib','Isha']){
    const [hh,mm]=times[p].split(':').map(Number);
    const mins=hh*60+mm;
    if(mins>nowMin) return {name:p,time:times[p],inMin:mins-nowMin};
  }
  const [fh,fm]=times.Fajr.split(':').map(Number);
  return {name:'Fajr',time:times.Fajr,inMin:(24*60-nowMin)+(fh*60+fm)};
}
// Bulle discrète (pas un bouton) tant que la permission navigateur n'a jamais
// été tranchée — sans elle, l'utilisateur qui laisse les réglages sur leur
// valeur par défaut ("activé") ne tape jamais sur un toggle et la popup
// système d'iOS n'apparaît donc jamais (voir requestNotifPermCTA). Une croix
// permet de la retirer définitivement (P.notifPromptDismissed) sans agir.
function dismissNotifBubble(e){ if(e) e.stopPropagation(); P.notifPromptDismissed=true; saveAll(); const active=document.querySelector('.nb.on'); if(active) nav(active.dataset.s); }
// Notification.permission est demandé au système à chaque lecture (coûteux, et l'Accueil se
// redessine souvent) : la bulle le relit au plus toutes les 3 secondes.
let _npCache={v:null,t:0};
function notifPermCached(){ const n=Date.now(); if(n-_npCache.t>3000){ _npCache.v=('Notification'in window)?Notification.permission:'unsupported'; _npCache.t=n; } return _npCache.v; }
function notifPermBubbleHTML(){
  if(P.notifPromptDismissed) return '';
  if(notifPermCached()!=='default') return '';
  return '<div class="row" style="align-items:center;gap:10px;padding:11px 12px;border-radius:16px;background:rgba(var(--e-rgb),.10);border:1px solid rgba(var(--e-rgb),.28);margin-bottom:12px">'+
    '<span style="display:inline-flex;flex-shrink:0">'+ICN('bell',17,'var(--e)')+'</span>'+
    '<span style="flex:1;font-size:12.5px;line-height:1.4;cursor:pointer" onclick="requestNotifPermCTA()">'+t('notifBubbleText')+' <b style="color:var(--et,var(--e))">'+t('notifBubbleAction')+'</b></span>'+
    '<span onclick="dismissNotifBubble(event)" style="flex-shrink:0;padding:4px;cursor:pointer;color:var(--dim)">'+ICN('close',15)+'</span>'+
  '</div>';
}
function homePrayerCardHTML(){
  const np=nextPrayerInfo();
  const h=Math.floor(np.inMin/60), m=np.inMin%60;
  const cd=fmtCountdown(h,m);
  return '<div class="hv7-day ik-prayer-card" style="padding:14px 16px;margin-bottom:12px" onclick="openPrayerFromHome()">'+
    '<div class="row" style="justify-content:space-between;align-items:center">'+
      '<div class="row" style="gap:10px;align-items:center">'+ICN('mosque',20,'var(--e)')+
        '<div><div style="font-weight:800;font-size:14px">'+t('nextPrayerLabel')+' · '+trPrayer(np.name)+'</div>'+
        '<div style="font-size:12px;color:var(--muted)">'+np.time+' · '+tp('inTimeLabel',cd)+'</div></div></div>'+
      ICN('chevronR',16,'var(--dim)')+
    '</div></div>';
}
// Retour depuis la prière ouverte par la carte de l'Accueil : on revient sur l'Accueil
// (et non sur la liste des outils, que le mode simplifié ne montre même pas dans la barre).
function openPrayerFromHome(){ outilsFrom='_back'; outilsTab='priere'; nav('outils'); }
/* Prière toujours à l'heure (V3.5.0) : la carte de l'Accueil était calculée une seule fois,
   à l'affichage — l'app restée ouverte gardait « dans 29 min » pour toujours, et la prière
   passée restait annoncée. On la recalcule chaque minute tant qu'elle est à l'écran, dès que
   l'app revient au premier plan, et l'outil Prière suit la prière en cours de la même façon. */
function refreshPrayerUI(){
  if(document.hidden) return;
  const c=document.querySelector('#s-home.on .ik-prayer-card');
  if(c){ const tmp=document.createElement('div'); tmp.innerHTML=homePrayerCardHTML(); const n=tmp.firstElementChild;
    if(n && n.innerHTML!==c.innerHTML){ c.innerHTML=n.innerHTML; } }
  if(document.body.dataset.scr==='outils' && outilsTab==='priere' && $('#outBody')) renderPriere();
}
setInterval(refreshPrayerUI,20000);
document.addEventListener('visibilitychange',()=>{ if(!document.hidden) refreshPrayerUI(); });

/* ---------- PROFIL ---------- */
function age(){ if(!P.bday)return'—'; const d=new Date(P.bday); return Math.floor((Date.now()-d)/31557600000); }
function avatarHTML(size,fs){
  // Photo validée (et non simplement échappée) : une valeur restaurée depuis un
  // fichier importé ou une synchro pourrait sinon fermer l'attribut style et
  // injecter du HTML ici, ce sink n'ayant historiquement aucun échappement.
  const ph=safePhotoUrl(P.photo);
  if(ph) return '<div style="width:'+size+'px;height:'+size+'px;border-radius:50%;background-image:url(\''+ph+'\');background-size:cover;background-position:center;margin:0 auto;border:2.5px solid rgba(var(--e-rgb),.35);box-shadow:0 6px 18px -6px rgba(var(--e-rgb),.4)"></div>';
  return '<div style="width:'+size+'px;height:'+size+'px;border-radius:50%;background:linear-gradient(135deg,var(--e),var(--marineL));display:flex;align-items:center;justify-content:center;margin:0 auto;font-family:Unbounded,system-ui,-apple-system,sans-serif;font-weight:800;font-size:'+fs+'px;border:2.5px solid rgba(var(--e-rgb),.35);box-shadow:0 6px 18px -6px rgba(var(--e-rgb),.4)">'+(P.name?P.name[0].toUpperCase():'?')+'</div>';
}
function renderProfile(){
  if(P.easyMode){ $('#s-profil').innerHTML=renderProfileSimple(); return; }
  const xp=xpProgress();
  const rk=rankFor(XP.level||1);
  const compDays=P.compDate?daysBetween(new Date(),new Date(P.compDate)):null;
  const langInfo=LANGS.find(l=>l[0]===curLang())||LANGS[0];
  let h='';
  // ===== HERO — avatar + nom + email/bio, épuré (image de référence : Profil) =====
  h+='<div class="card stag pf-hero" style="animation-delay:0s"><div class="pf-avwrap">'+avatarHTML(88,34)+
    '<div class="pf-cam" onclick="changePhoto()">'+ICN('camera',16)+'</div></div>';
  h+='<div class="pf-name-row"><div class="man" style="font-weight:800;font-size:20px">'+escHtml(P.name||t('athleteDefault'))+'</div>'+
    '<div class="pf-edit" onclick="openProfileEdit()" title="'+t('editInfos')+'">'+ICN('edit',16)+'</div></div>';
  h+='<div style="font-size:12.5px;color:var(--muted);margin-top:3px" onclick="editBio()">'+escHtml(window.currentUserEmail||P.bio||t('addBioPrompt'))+'</div>';
  h+='<div class="rankchip" style="margin-top:11px;background:'+rk.bg+';color:#fff">'+t('level')+' '+XP.level+' · '+rk.name+' · '+XP.total+' XP</div>';
  // V4.11.4 : l'aperçu tient dans le héros, en trois tuiles (avant : une carte de 4 lignes dont 3
  // ouvraient la même fiche, et un « Objectif » qui doublonnait l'onglet Sport).
  h+='<div class="pf-tiles">'+
    '<button type="button" class="pf-tile" onclick="bfFlowOpen()"><b>'+(P.height?escHtml(P.height)+' <small>cm</small>':'—')+'</b><span>'+(P.weight?escHtml(String(P.weight).replace('.',curLang()==='en'?'.':','))+' kg':t('heightWeight'))+'</span></button>'+
    '<button type="button" class="pf-tile" onclick="openProfileEdit()"><b>'+age()+'</b><span>'+t('age')+'</span></button>'+
    '<button type="button" class="pf-tile" onclick="openRecords()"><b>'+(getUserVDOT()?fmt1(getUserVDOT()):'—')+'</b><span>VDOT'+(P.vdotEstimated?' ≈':'')+'</span></button>'+
  '</div>';
  h+='</div>';
  // ===== PROGRESSION — badges intégrés directement au profil =====
  // Un palier atteint depuis la dernière vérification (le temps qui passe, par exemple) est
  // débloqué ici : avant, la carte disait « aucun badge » puis « palier atteint · 100 % ».
  { checkNewBadges(false); const unlocked=unlockedBadges(); const recent=[...unlocked].sort((a,b)=>b.date<a.date?-1:1).slice(0,5).map(u=>BADGE_TIERS.find(b=>b.key===u.key)).filter(Boolean);
    h+='<div class="sec-head stag" style="animation-delay:.06s"><h3 class="grp-lab" style="margin:0">'+t('progression')+'</h3><span class="see" onclick="openBadges()">'+tp('seeAllProgress',unlocked.length,BADGE_TIERS.length)+'</span></div>';
    h+='<div class="card stag" style="animation-delay:.07s">';
    if(recent.length){
      h+='<div class="row" style="gap:10px;flex-wrap:wrap;justify-content:flex-start">'+recent.map(b=>'<div class="bd-icon '+b.cls+'" style="width:52px;height:52px;cursor:pointer" onclick="openBadgeQuick(\''+b.key+'\')">'+bdGlyph(b.key)+'</div>').join('')+'</div>';
    } else {
      h+='<div style="font-size:12px;color:var(--muted)">'+tp('noBadgeYet',(nextBadge()||BADGE_TIERS[0]).name)+'</div>';
    }
    const nb=nextBadge();
    if(nb){
      const prog=badgeProgress(nb);
      h+='<div style="margin-top:14px;padding-top:12px;border-top:1px solid var(--hair)"><div class="row" style="margin-bottom:6px"><span style="font-size:12px;color:var(--muted)">'+tp('nextBadgeLab',nb.name)+'</span><span class="mono" style="font-size:12px;color:var(--et,var(--e))">'+prog.pct+'%</span></div><div class="pbar" style="height:6px"><div style="width:'+prog.pct+'%"></div></div><div style="font-size:11.5px;color:var(--muted);margin-top:7px;line-height:1.4">'+badgeHintText(prog)+'</div></div>';
    }
    h+='</div>';
  }
  // ===== SECTIONS GROUPÉES (V3.10.3) — trois groupes, plus aucun doublon :
  // · « Gérer le profil » doublonnait le crayon du haut et les lignes Taille / Âge (qui
  //   ouvrent maintenant la fiche) ; « Statistiques » doublonnait l'onglet du bas ;
  // · le Thème est réglé sur la fiche Apparence, avec la couleur et la matière ;
  // · Mot de passe et Données ouvrent une seule fiche « Compte et données » ;
  // · Conditions et Confidentialité, une seule fiche (avec un sélecteur). =====
  // V4.11.4 : trois groupes courts. Langue rangée avec l'Apparence, l'aide (tutoriel, méthode,
  // installation, commentaire, conditions) dans une seule fiche « Aide et infos », les courses avec le suivi.
  const row=(icon,label,onclick,val,cls)=>'<div class="grp-row'+(cls?' '+cls:'')+'" onclick="'+onclick+'"><div class="lr-icon">'+ICN(icon,20,'currentColor')+'</div><div class="lr-title">'+label+'</div>'+(val?'<div class="lr-val">'+val+'</div>':'')+'<span class="lr-chev">'+ICN('chevronR',16)+'</span></div>';
  h+='<div class="grp-lab stag" style="animation-delay:.09s">'+t('trackingLab')+'</div>';
  h+='<div class="grp-card stag" style="animation-delay:.10s">'+
    row('medal',t('historyRecords'),'openRecords()')+
    row('users',t('friendsRanking'),'openFriends()')+
    row('flag',t('myClubLab'),'openClub()','','pf-club-row')+
    row('calendar',t('racesTitle'),'openRaces()')+
  '</div>';
  h+='<div class="grp-lab stag" style="animation-delay:.12s">'+t('prefsLab')+'</div>';
  h+='<div class="grp-card stag" style="animation-delay:.13s">'+
    row('palette',t('appearLangLab'),"openProfileSection('appearance')",colorDotNow()+colorNameNow()+' · '+langInfo[1])+
    row('bell',t('notifsApp'),"openProfileSection('notif')")+
    '<div class="grp-row no-chev"><div class="lr-icon">'+ICN('heart',20,'currentColor')+'</div><div><div class="lr-title">'+t('simplifiedMode')+'</div><div style="font-size:11px;color:var(--muted);margin-top:2px;max-width:200px">'+t('simplifiedModeDesc')+'</div></div><div class="toggle'+(P.easyMode?' on':'')+'" onclick="event.stopPropagation();toggleEasyMode()"></div></div>'+
  '</div>';
  h+='<div class="grp-lab stag" style="animation-delay:.15s">'+t('accountHelpLab')+'</div>';
  h+='<div class="grp-card stag" style="animation-delay:.16s">'+
    row('lock',t('accountDataLab'),"openProfileSection('account')",escHtml(window.currentUserEmail||(window.isGuestUser?t('guestModeLabel'):t('notConnected'))))+
    row('help',t('helpInfoLab'),"openProfileSection('help')")+
    '<div id="pfAdminRows"></div>'+
  '</div>';
  // (le numéro de version est désormais dans la signature IKORUN en bas de chaque écran)
  swapIn('s-profil',h);
  // V4.0.0 : outils de l'admin de l'app (statistiques, calendrier), vérifiés côté serveur
  ikIsAdmin().then(a=>{ const el=document.getElementById('pfAdminRows'); if(a && el) el.innerHTML=
    '<div class="grp-row" onclick="openAppStats()"><div class="lr-icon">'+ICN('chart',20,'currentColor')+'</div><div class="lr-title">'+t('stTitle')+'</div><span class="lr-chev">'+ICN('chevronR',16)+'</span></div>'+
    '<div class="grp-row" onclick="openRaces({admin:true})"><div class="lr-icon">'+ICN('gear',20,'currentColor')+'</div><div class="lr-title">'+t('rcAdmin')+'</div><span class="lr-chev">'+ICN('chevronR',16)+'</span></div>'; });
}
function renderProfileSimple(){
  const rk=rankFor(XP.level||1);
  const compDays=P.compDate?daysBetween(new Date(),new Date(P.compDate)):null;
  let h='';
  h+='<div class="card stag pf-hero" style="animation-delay:0s;text-align:center"><div class="pf-avwrap">'+avatarHTML(72,28)+'</div>'+
    '<div class="man" style="font-weight:800;font-size:18px;margin-top:8px">'+escHtml(P.name||t('athleteDefault'))+'</div>'+
    '<div style="font-size:12px;color:var(--muted);margin-top:2px">'+age()+' '+(curLang()==='en'?'yo':curLang()==='ar'?'سنة':'ans')+' · VDOT '+(getUserVDOT()||'—')+(compDays!==null&&compDays>=0?' · J-'+compDays:'')+'</div>'+
    '<div class="rankchip" style="margin-top:10px;background:'+rk.bg+';color:#fff;display:inline-block">'+t('level')+' '+XP.level+' · '+rk.name+'</div></div>';

  // Trois groupes au rôle clair. Avant, le thème, la langue, les notifications et les
  // records n'étaient joignables qu'en quittant le mode simplifié ; « Statistiques »
  // doublonnait l'onglet du bas.
  const row=(icon,label,onclick,val)=>'<div class="grp-row" onclick="'+onclick+'"><div class="lr-icon">'+ICN(icon,20,'currentColor')+'</div><div class="lr-title">'+label+'</div>'+(val?'<div class="lr-val">'+val+'</div>':'')+'<span class="lr-chev">'+ICN('chevronR',16)+'</span></div>';
  const langInfo=LANGS.find(l=>l[0]===curLang())||LANGS[0];
  h+='<div class="grp-lab">'+t('yourSpace')+'</div>';
  h+='<div class="grp-card">'+
    row('edit',t('editMyProfile'),'openProfileEdit()')+
    row('scale',t('bodyRowLab'),'bfFlowOpen()',P.height&&P.weight?escHtml(P.height)+' cm · '+escHtml(P.weight)+' kg':'')+
    row('medal',t('historyRecords'),'openRecords()')+
    row('star',t('badgesLabel'),'openBadges()')+
    row('users',t('friendsRanking'),'openFriends()')+
    row('flag',t('myClubLab'),'openClub()').replace('class="grp-row"','class="grp-row pf-club-row"')+
  '</div>';
  h+='<div class="grp-lab">'+t('settings')+'</div>';
  h+='<div class="grp-card">'+
    '<div class="grp-row no-chev"><div class="lr-icon">'+ICN('heart',20,'currentColor')+'</div><div class="lr-txt"><div class="lr-title">'+t('simplifiedMode')+'</div><div class="lr-sub">'+t('simplifiedModeDesc')+'</div></div><div class="toggle on" onclick="event.stopPropagation();toggleEasyMode()"></div></div>'+
    row('palette',t('appearLangLab'),"openProfileSection('appearance')",colorNameNow()+' · '+langInfo[1])+
    row('bell',t('notifsApp'),"openProfileSection('notif')")+
  '</div>';
  h+='<div class="grp-lab">'+t('support')+'</div>';
  h+='<div class="grp-card">'+
    row('lock',t('accountDataLab'),"openProfileSection('account')")+
    row('help',t('helpInfoLab'),"openProfileSection('help')")+
  '</div>';
  // La signature de bas d'écran est masquée en mode simplifié : la version reste lisible ici.
  h+='<div class="ez-ver">IKORUN · V'+APP_VERSION+'</div>';
  return h;
}
/* ---- Fiches de réglages du profil, ouvertes dans l'overlay générique ---- */
// V4.11.4 : « Aide et infos » réunit ce qui ne sert qu'une fois de temps en temps
function pfHelpHTML(){
  const row=(icon,label,onclick)=>'<div class="grp-row" onclick="'+onclick+'"><div class="lr-icon">'+ICN(icon,20,'currentColor')+'</div><div class="lr-title">'+label+'</div><span class="lr-chev">'+ICN('chevronR',16)+'</span></div>';
  return '<div class="grp-card">'+
    row('comment',t('sendFeedbackLab'),"closeOv('ovProg');openFeedback()")+
    row('flag',t('replayTourBtn'),"closeOv('ovProg');startAppTour()")+
    row('bulb',t('mtTitle'),"closeOv('ovProg');openMethod()")+
    (isStandalone()?'':row('download',t('installAppBtn'),"closeOv('ovProg');installApp()"))+
    row('shield',t('legalLab'),"openProfileSection('legal')")+
  '</div>';
}
let _pfSheet=null;
let _legalTab='terms';
function openProfileSection(key){
  const toColor=key==='color'; if(toColor) key='appearance'; // l'ancienne fiche Couleur fait partie d'Apparence
  // V3.10.3 : Données fait partie de Compte ; Conditions et Confidentialité partagent une fiche
  if(key==='data') key='account';
  if(key==='terms'||key==='privacy'){ _legalTab=key; key='legal'; }
  _pfSheet=key;
  const titles={help:t('helpInfoLab'),account:t('accountDataLab'),lang:''+t('language'),appearance:''+t('appearLangLab'),theme:t('txTitle'),notif:''+t('notifsApp'),legal:t('legalLab')};
  $('#ovProgTitle').textContent=titles[key]||t('settings');
  $('#progBody').innerHTML=pfSectionHTML(key);
  { const sc=$('#ovProg .ov-body-scroll'); if(sc && !toColor) sc.scrollTop=0; } // V3.14.0 : une nouvelle fiche s'ouvre en haut (elle gardait le défilement de la précédente)
  openOv('ovProg');
  if(toColor) setTimeout(()=>{ const c=$('#apColor'); if(c) c.scrollIntoView({block:'start'}); },60);
}
function refreshPfSheet(){ if(_pfSheet && $('#ovProg').classList.contains('on')) $('#progBody').innerHTML=pfSectionHTML(_pfSheet); }
function pfSectionHTML(key){
  if(key==='account') return pfAccountHTML()+pfDataHTML();
  if(key==='lang') return pfLangHTML();
  if(key==='appearance') return '<div class="lab ap-lab">'+t('language')+'</div>'+pfLangHTML()+pfAppearanceHTML();
  if(key==='help') return pfHelpHTML();
  if(key==='theme') return pfThemeEditorHTML();
  if(key==='notif') return pfNotifHTML();
  if(key==='legal') return '<div class="seg-ctrl sub" data-seg="legal" style="margin-bottom:6px">'+
    [['terms','termsOfUseLab'],['privacy','privacyPolicyLab']].map(([k,l])=>'<div class="seg-btn'+(_legalTab===k?' on':'')+'" onclick="_legalTab=\''+k+'\';refreshPfSheet()">'+t(l)+'</div>').join('')+'</div>'+
    (_legalTab==='privacy'?legalPrivacyHTML():legalTermsHTML());
  return '';
}
/* ---------- CGU & CONFIDENTIALITÉ ----------
   Contenu juridique volontairement gardé en français uniquement (langue de
   référence), quelle que soit la langue de l'app : un texte légal traduit
   à la volée risquerait de perdre en précision. Mentions légales (art. 13)
   remplies le 20/09 avant diffusion élargie — éditeur particulier, adresse
   volontairement omise (facultatif pour un particulier non-professionnel).
   Reste à faire évoluer si l'app devient payante/commerciale un jour (cf.
   texte de l'art. 13 lui-même) — pas une relecture juridique professionnelle. */
const LEGAL_LAST_UPDATE='12 octobre 2026';
function legalP(title,body){ return '<div style="font-weight:800;font-size:13.5px;margin:16px 0 6px;color:var(--snow)">'+title+'</div><div style="font-size:12.5px;color:var(--muted);line-height:1.65">'+body+'</div>'; }
function legalWrapHTML(bodyHtml){
  return '<div class="card" style="padding:16px">'+
    '<div style="font-size:11px;color:var(--dim);margin-bottom:2px">Dernière mise à jour : '+LEGAL_LAST_UPDATE+'</div>'+
    '<div style="font-size:11px;color:var(--dim);margin-bottom:4px">Document de référence rédigé en français.</div>'+
    bodyHtml+
    '</div>';
}
function legalTermsHTML(){
  const b=legalP('1. Objet',
    'Les présentes Conditions Générales d’Utilisation (« CGU ») régissent l’accès et l’utilisation de l’application IKORUN (« l’Application »), une application de coaching sportif (course à pied et musculation) éditée par IKORUN, ci-après « l’Éditeur ». En créant un compte ou en utilisant l’Application, tu acceptes sans réserve les présentes CGU.')
  +legalP('2. Description du service',
    'IKORUN propose : la génération de plans d’entraînement personnalisés (course à pied et musculation) à partir des informations que tu renseignes (niveau, objectif, performances passées…) ; le suivi de tes séances, statistiques et progrès ; des fonctionnalités sociales optionnelles (ajout d’amis et classement entre amis, création ou adhésion à un club via un code à 6 caractères avec classement entre membres du club) ; des outils de calcul (allures, VDOT, etc.) ; un formulaire d’avis qui ouvre ton application mail avec un message pré-rempli, rien n’étant envoyé sans que tu appuies toi-même sur « Envoyer ». L’Application fonctionne en mode « invité » (sans compte permanent) ou avec un compte (email/mot de passe ou connexion Google). IKORUN est distribuée uniquement comme application web installable depuis ton navigateur : elle n’est présente ni sur l’App Store ni sur le Play Store.')
  +legalP('3. Avertissement santé et sport — à lire attentivement',
    'IKORUN n’est pas un dispositif médical et ne fournit aucun avis médical. Les plans d’entraînement générés le sont par des algorithmes génériques et ne remplacent pas l’avis d’un professionnel de santé. Avant de commencer tout programme, en particulier en cas d’antécédents médicaux, de condition de santé particulière, ou de reprise d’activité après une longue interruption, consulte un médecin. Tu es seul(e) responsable de l’évaluation de ta condition physique et des risques liés à la pratique sportive. L’Éditeur ne pourra être tenu responsable de blessures, malaises ou dommages résultant de l’utilisation des plans ou conseils fournis par l’Application.')
  +legalP('4. Compte utilisateur',
    'Tu es responsable de la confidentialité de tes identifiants et de toute activité effectuée depuis ton compte. Les informations fournies doivent être exactes. Tu peux à tout moment exporter tes données depuis Profil > Compte et données, et supprimer définitivement ton compte depuis Profil > Compte > Zone de danger.')
  +legalP('5. Contenu et comportement',
    'Ton nom d’utilisateur, ta photo de profil et les contenus que tu partages via les fonctionnalités sociales doivent rester respectueux, ne pas usurper l’identité d’un tiers, et respecter la loi. L’Éditeur se réserve le droit de suspendre ou supprimer tout compte enfreignant ces règles.')
  +legalP('6. Propriété intellectuelle',
    'L’Application, son design, sa marque et son contenu (hors contenu fourni par les utilisateurs) sont la propriété de l’Éditeur ou de ses partenaires et protégés par le droit de la propriété intellectuelle. Certaines images d’exercices proviennent de la base de données publique « free-exercise-db » (domaine public).')
  +legalP('7. Disponibilité du service',
    'L’Éditeur s’efforce d’assurer un accès continu à l’Application, sans garantir une disponibilité ininterrompue (maintenance, mise à jour, cas de force majeure). L’Application fonctionne partiellement hors-ligne mais nécessite une connexion pour la synchronisation cloud, la connexion et les fonctionnalités sociales.')
  +legalP('8. Limitation de responsabilité',
    'Dans les limites permises par la loi, l’Éditeur ne pourra être tenu responsable des dommages indirects résultant de l’utilisation ou de l’impossibilité d’utiliser l’Application, ni de l’exactitude parfaite des calculs, statistiques ou plans générés, fournis « en l’état ».')
  +legalP('8 bis. Fonctionnalités payantes',
    'À ce jour, l’Application est intégralement gratuite et ne comporte aucun paiement ni aucun abonnement. Des fonctionnalités payantes sont envisagées à l’avenir ; si elles sont introduites, elles seront annoncées clairement avant toute souscription et les règles suivantes s’appliqueront. Le prix affiché sera en euros toutes taxes comprises. Un abonnement sera souscrit pour la période choisie et se renouvellera automatiquement à son terme, sauf résiliation avant la fin de la période en cours ; la résiliation prendra effet à l’échéance et l’accès restera ouvert jusque-là. Le paiement sera traité par un prestataire externe (par exemple Stripe) : l’Éditeur n’aura jamais accès à ton numéro de carte, seul le prestataire le traitera, conformément à sa propre politique de confidentialité. IKORUN reste distribuée exclusivement comme application web (PWA) et ne sera jamais publiée sur l’App Store ni sur le Play Store. Conformément à l’article L221-18 du code de la consommation, tu disposeras d’un délai de rétractation de quatorze jours à compter de la souscription ; toutefois, en demandant l’accès immédiat à une fonctionnalité payante, tu demanderas expressément l’exécution du contrat avant la fin de ce délai et renonceras à ton droit de rétractation pour la partie déjà exécutée, ce qui te sera rappelé au moment du paiement. En cas de défaut de paiement, l’accès aux fonctionnalités payantes serait suspendu, mais tes données et ton compte resteraient conservés et exportables. Aucune fonctionnalité déjà utilisée gratuitement ne deviendra payante de façon rétroactive sans préavis d’au moins trente jours.')
  +legalP('8 ter. Publicité',
    'À ce jour, l’Application n’affiche aucune publicité. Des espaces publicitaires sont envisagés à l’avenir pour financer le service sans faire reposer son fonctionnement uniquement sur les fonctionnalités payantes. S’ils sont introduits, ils seront toujours clairement identifiés comme tels (jamais déguisés en contenu ou en conseil sportif), sans jamais interrompre une séance en cours ni s’afficher pendant le suivi d’un entraînement actif. Une publicité pour un produit de santé, complément alimentaire ou dispositif médical serait exclue par principe, compte tenu de la nature sportive et santé de l’Application. Le recours à des publicités personnalisées (basées sur ton comportement) plutôt que contextuelles ferait l’objet d’une demande de consentement explicite et révocable à tout moment, conformément à la réglementation ePrivacy et au RGPD — voir l’article 3 bis de la Politique de confidentialité. Tu pourras toujours utiliser gratuitement les fonctionnalités existantes de l’Application même en refusant les publicités personnalisées.')
  +legalP('9. Résiliation',
    'Tu peux cesser d’utiliser l’Application et supprimer ton compte à tout moment. L’Éditeur peut suspendre ou résilier l’accès d’un utilisateur en cas de violation des présentes CGU.')
  +legalP('10. Modification des CGU',
    'L’Éditeur peut modifier les présentes CGU à tout moment, notamment pour refléter une évolution de l’Application ou de la réglementation. La date de dernière mise à jour figure en haut de ce document ; toute modification substantielle te sera signalée dans l’Application.')
  +legalP('11. Droit applicable et litiges',
    'Les présentes CGU sont soumises au droit français. En cas de difficulté, commence par contacter l’Éditeur à l’adresse indiquée ci-dessous : la plupart des situations se règlent ainsi. À défaut d’accord, tu peux recourir gratuitement à un médiateur de la consommation, ou utiliser la plateforme européenne de règlement en ligne des litiges (ec.europa.eu/consumers/odr). Si aucune solution amiable n’aboutit, le litige relève des tribunaux français compétents ; en qualité de consommateur, tu peux saisir la juridiction de ton lieu de résidence.')
  +legalP('12. Contact',
    'Pour toute question relative aux présentes CGU : ikorunn@gmail.com.')
  +legalP('13. Mentions légales',
    'Éditeur de l’Application : Hamou, particulier. Directeur de la publication : Hamou. Contact : ikorunn@gmail.com. '
   +'Hébergement : l’Application est hébergée par Cloudflare, Inc. (101 Townsend St, San Francisco, CA 94107, États-Unis) et ses données par Supabase, Inc. sur des serveurs situés dans l’Union européenne (Irlande). '
   +'Ces mentions sont exigées par l’article 6 de la loi pour la confiance dans l’économie numérique. L’Application reste à ce jour entièrement gratuite et non professionnelle : l’identification ci-dessus (nom et adresse de contact) satisfait cette obligation à ce stade. Dès la première fonctionnalité payante ou toute activité commerciale, une adresse postale complète et, le cas échéant, un numéro SIREN devront être ajoutés.');
  return legalWrapHTML(b);
}
function legalPrivacyHTML(){
  const b=legalP('1. Responsable du traitement',
    'Le responsable du traitement des données à caractère personnel collectées via IKORUN est l’éditeur de l’application, joignable à ikorunn@gmail.com.')
  +legalP('2. Données collectées',
    'Selon ton mode de connexion et ton usage de l’Application, nous traitons : les données de compte (email, mot de passe chiffré ou identifiant Google) ; les données de profil (prénom, date de naissance, sexe, taille, poids, niveau, objectifs, photo si tu en ajoutes une) ; les données d’entraînement et de ressenti que tu saisis (séances, performances, records, historique, mais aussi difficulté ressentie, fatigue, sommeil, douleurs éventuelles) ; les indicateurs calculés à partir de celles-ci (XP, niveau, VDOT, kilomètres et séances cumulés, série de jours consécutifs) ; les données sociales optionnelles (pseudo, liste d’amis, appartenance à un club) si tu utilises ces fonctionnalités ; enfin les données techniques inhérentes à tout service en ligne, conservées par notre hébergeur (adresse IP, journaux de connexion) ainsi qu’un compteur anti-abus limitant le nombre d’actions sensibles par heure. Certaines de ces informations touchent à ta santé (poids, douleurs, fatigue) : tu les saisis librement et rien ne t’oblige à les renseigner. IKORUN n’enregistre pas ta localisation GPS. Pour la météo, tu choisis ta ville ou ta wilaya, ou tu touches « Me localiser » : ta position est alors arrondie à environ 1 km, gardée dans ton profil et envoyée uniquement au service météo (voir article 6). Si tu suis une course du calendrier, son identifiant est enregistré pour t’envoyer les rappels (un mois, une semaine et la veille) ; si tu proposes une course, ta proposition et ton pseudo sont visibles de l’équipe qui la vérifie. Le mode « invité » crée lui aussi un compte technique sur nos serveurs, avec un pseudo attribué automatiquement. Si tu actives les notifications, nous conservons également un identifiant technique d’abonnement fourni par ton navigateur (propre à cet appareil), ta langue d’affichage, ainsi que le titre de ta séance du jour et son statut fait/pas fait — ces deux dernières informations étant les seules données d’entraînement à sortir du chiffrement local, uniquement pour permettre l’envoi du rappel. Si tu actives, dans ton club, le partage de ton état d’entraînement, nous conservons aussi ta charge d’entraînement, ta forme du jour et la présence ou non d’une douleur — et la zone et l’intensité de cette douleur seulement si tu l’as accepté séparément (voir article 5). Enfin, si tu actives les rappels de prière, nous conservons ce choix : il révèle une pratique religieuse, c’est-à-dire une donnée sensible au sens de l’article 9 du RGPD, traitée sur la seule base de ton consentement explicite. Tu peux le retirer à tout moment en désactivant ces rappels dans Profil > Notifications, ce qui efface aussitôt cette information.')
  +legalP('3. Finalités',
    'Ces données sont utilisées pour fournir le service (génération de plans, suivi, statistiques), synchroniser tes données entre tes appareils, permettre les fonctionnalités sociales optionnelles que tu actives, et protéger le service contre les abus. Elles ne sont ni vendues ni louées. À ce jour, elles ne servent à aucune publicité personnalisée — voir l’article 3 bis pour une évolution possible de ce point.')
  +legalP('3 bis. Publicité — évolution possible',
    'L’Application n’affiche aujourd’hui aucune publicité et ne partage aucune donnée à des fins publicitaires. Si des espaces publicitaires sont introduits à l’avenir (voir CGU, article 8 ter), deux cas seront distingués. Une publicité contextuelle (liée au contenu affiché, sans suivi de ton comportement) pourra être mise en place sans consentement préalable, comme le permet la réglementation. Une publicité personnalisée (basée sur ton profil ou ton comportement dans l’Application) nécessitera en revanche ton consentement explicite, recueilli via une demande claire que tu pourras accepter ou refuser librement, et retirer à tout moment depuis Profil > Compte et données sans perdre l’accès à l’Application. Le ou les partenaires publicitaires éventuels et les données précises qui leur seraient transmises seront décrits ici, dans cet article, avant toute activation.')
  +legalP('4. Base légale',
    'Le traitement repose sur l’exécution du contrat qui te lie à l’Éditeur (fourniture du service demandé) et, pour les fonctionnalités optionnelles (photo, réseau social), sur ton consentement.')
  +legalP('5. Données visibles par d’autres utilisateurs',
    'Certaines fonctionnalités font volontairement sortir des données de ton espace privé — c’est leur raison d’être, et elles restent facultatives. Ton profil public (pseudo, photo, niveau, XP, VDOT, kilomètres et séances cumulés, série de jours) est visible par tes amis acceptés et par les membres de ton club. Les autres utilisateurs ne peuvent pas parcourir la liste des profils : ils doivent connaître ton pseudo exact pour te trouver, et cette recherche ne leur renvoie alors que ton pseudo et ton niveau — jamais tes statistiques ni ta photo. Si tu crées ou rejoins un club, ton pseudo, ta photo, ton niveau et ton XP apparaissent dans le classement de ce club : toute personne détenant le code à 6 caractères du club peut le rejoindre et voir ces informations. En revanche, le détail de tes séances, tes ressentis, tes douleurs et tes mesures corporelles ne sont JAMAIS partagés, ni avec tes amis, ni avec les membres de ton club. Tu peux quitter un club ou retirer un ami à tout moment, ce qui te retire aussitôt du classement correspondant. Partage avec l’encadrement du club (facultatif, désactivé par défaut) : si tu l’actives, le propriétaire et les administrateurs de tes clubs voient ta charge d’entraînement, ta forme du jour et si tu as une douleur ; la zone et l’intensité de la douleur ne leur sont montrées que si tu coches aussi cette option. Les autres membres ne voient rien de tout cela. Tu peux couper ce partage à tout moment dans l’onglet Club. Seule exception, technique et non sociale : si tu actives les rappels de notification, le TITRE de la séance du jour et son statut fait/pas fait (jamais le RPE, la douleur, les allures ni le détail complet) sortent du stockage chiffré de ton appareil pour permettre au serveur de te notifier même l’Application fermée ; désactive les rappels dans Profil > Notifications pour arrêter cet envoi.')
  +legalP('6. Hébergement et destinataires',
    'Tes données sont hébergées chez Supabase, sur des serveurs situés dans l’Union européenne (Irlande). Y ont accès : l’Éditeur ; Supabase en tant qu’hébergeur ; les autres utilisateurs, uniquement dans les limites décrites à l’article précédent. Si tu choisis la connexion Google, celle-ci est gérée par Google LLC selon sa propre politique de confidentialité, ce qui implique un transfert vers les États-Unis encadré par le cadre de protection des données UE–États-Unis. Par ailleurs, pour afficher les polices de caractères, charger une bibliothèque technique et afficher les images d’exercices, ton navigateur contacte trois services externes : Google Fonts, jsDelivr et GitHub. Ces services reçoivent de ce fait ton adresse IP, sans qu’aucune donnée d’entraînement ne leur soit transmise. Tu peux les bloquer avec une extension de navigateur : l’Application reste utilisable, avec un affichage dégradé. Météo : si tu choisis un lieu, ton navigateur interroge Open-Meteo (Suisse, données sous licence CC BY 4.0) avec les coordonnées arrondies de ce lieu, sans identifiant ni donnée d’entraînement. Carte d’une course : elle n’est chargée depuis OpenStreetMap que si tu touches « Afficher la carte ». Mesure d’audience du site : Cloudflare Web Analytics (Cloudflare Inc.) compte les visites sans cookie et sans identifiant personnel. Si tu actives les notifications, l’envoi passe obligatoirement par le service de notification de ton système : Apple Push Notification Service (Apple Inc., États-Unis) sur iPhone et iPad, Firebase Cloud Messaging (Google LLC, États-Unis) sur Android et Chrome. Ces services reçoivent l’identifiant d’abonnement de ton appareil et le contenu de la notification — pour un rappel de séance, cela inclut le titre de la séance concernée. Désactiver les notifications dans Profil > Notifications met fin à ces transferts.')
  +legalP('7. Durée de conservation et suppression',
    'Tes données sont conservées tant que ton compte est actif. Un compte resté sans aucune connexion pendant trois ans est considéré comme inactif : il est supprimé, avec toutes les données associées, après un email de relance resté sans réponse pendant un mois (pour un compte invité, sans email connu, la suppression intervient directement au terme des trois ans). Tu peux exporter une copie complète au format JSON depuis Profil > Compte et données, et supprimer définitivement ton compte depuis Profil > Compte > Zone de danger. La suppression efface ton compte, ton profil public, tes données d’entraînement, tes liens d’amitié, ton appartenance à un club et les clubs dont tu es propriétaire ; elle est immédiate et irréversible. Attention à ne pas confondre avec « Réinitialiser », dans Données & confidentialité, qui n’efface que cet appareil et laisse ton compte intact. Les sauvegardes techniques de l’hébergeur peuvent conserver une copie résiduelle quelques jours avant d’être écrasées.')
  +legalP('8. Tes droits',
    'Conformément au RGPD, tu disposes d’un droit d’accès, de rectification, d’effacement, de portabilité (export JSON disponible dans l’Application), de limitation du traitement et d’opposition sur tes données. Tu peux également retirer à tout moment ton consentement aux fonctionnalités optionnelles (photo de profil, amis, club) — le retrait ne remet pas en cause ce qui a été fait avant. Tu peux enfin définir des directives sur le sort de tes données après ton décès. Pour exercer ces droits, utilise les outils intégrés à l’Application ou contacte ikorunn@gmail.com. Tu peux aussi introduire une réclamation auprès de la CNIL (www.cnil.fr).')
  +legalP('9. Décisions automatisées',
    'Tes plans d’entraînement sont générés et ajustés automatiquement par un moteur de règles qui fonctionne intégralement sur ton appareil, à partir des informations que tu renseignes. Aucune intelligence artificielle ni service tiers n’intervient dans ce calcul. Ces plans sont des suggestions sportives : ils ne produisent aucun effet juridique, et tu peux les modifier ou les ignorer à tout moment.')
  +legalP('10. Stockage local et cookies',
    'L’Application utilise le stockage local de ton navigateur (localStorage) pour fonctionner hors-ligne et mémoriser tes préférences, IndexedDB pour conserver la clé de chiffrement propre à ton appareil, et le cache d’un service worker pour l’affichage hors-ligne. Ces éléments restent sur ton appareil. Si tu actives les notifications, ton navigateur crée en plus un abonnement push propre à cet appareil, dont l’identifiant est enregistré sur nos serveurs jusqu’à ce que tu désactives les rappels ou supprimes ton compte. Aucun cookie publicitaire n’est utilisé ; voir l’article 3 bis si cela évolue.')
  +legalP('10 ter. Statistiques d’usage anonymes',
    'Pour savoir quelles fonctions servent et améliorer l’Application, IKORUN envoie des événements d’usage anonymes : le nom de l’action (par exemple « plan créé », « bilan de séance »), la langue, le type d’appareil (iPhone, Android, ordinateur), si l’app est installée, sa version et l’heure. Ils sont rattachés à un identifiant tiré au hasard sur ton appareil, jamais à ton compte, ton email, tes séances ni ta position. Ces événements sont conservés 400 jours puis effacés, et seul l’Éditeur en voit des totaux. Tu peux refuser à tout moment dans Profil > Compte et données > Statistiques anonymes : l’envoi s’arrête et l’identifiant est effacé de ton appareil. Si ton navigateur envoie le signal « Global Privacy Control », les statistiques sont désactivées tant que tu ne les actives pas toi-même. La base légale est l’intérêt légitime de l’Éditeur à mesurer l’usage de son service, avec ce droit d’opposition simple.')
  +legalP('10 bis. Notifications',
    'Les notifications sont facultatives et désactivées tant que tu n’as pas explicitement accepté la demande de ton navigateur. Quatre types existent : les rappels de course (un mois, une semaine et la veille d’une course que tu suis), les rappels d’entraînement, envoyés au maximum deux fois par jour (à 12h et 16h) uniquement si la séance prévue n’est pas encore faite, les rappels de prière, envoyés aux cinq horaires quotidiens si tu les as activés, et les records de tes amis (désactivés par défaut) : quand un ami ou un membre de ton club améliore son VDOT, tu en es informé — et, réciproquement, tant que ce réglage est actif, l’amélioration de ton propre VDOT (donnée déjà visible d’eux, voir §5) leur est annoncée ; jamais un chrono, une séance ou un ressenti. Chaque type dispose de son propre interrupteur dans Profil > Notifications, et tu peux aussi les révoquer entièrement depuis les réglages de ton téléphone. Aucune notification commerciale ou promotionnelle n’est envoyée.')
  +legalP('11. Sécurité',
    'Sur ton appareil, tes données d’entraînement sont chiffrées (AES-GCM 256 bits) avant d’être stockées dans le navigateur ; la clé est générée localement, non exportable, et n’est envoyée nulle part. Les échanges avec le serveur passent par HTTPS. En revanche, sois conscient(e) que la copie sauvegardée sur nos serveurs n’est pas chiffrée de bout en bout : elle est techniquement lisible par l’hébergeur et par l’Éditeur, et protégée par les contrôles d’accès de la base de données ainsi que par le chiffrement disque de l’hébergeur. Aucun système n’est infaillible ; en cas de faille de sécurité avérée, tu en serais informé(e) conformément à la réglementation.')
  +legalP('12. Mineurs',
    'L’Application s’adresse aux personnes de 15 ans et plus. En dessous de cet âge, l’accord d’un parent ou tuteur légal est requis pour créer un compte, conformément à la réglementation française sur le consentement numérique. Cette règle n’est pas vérifiée automatiquement à l’inscription : elle relève de ta responsabilité, et celle du représentant légal pour un mineur.')
  +legalP('13. Modifications',
    'Cette politique peut évoluer ; la date de mise à jour est indiquée en haut de ce document.')
  +legalP('14. Contact',
    'Pour toute question relative à tes données : ikorunn@gmail.com.');
  return legalWrapHTML(b);
}
