// iOS n'affiche la popup système "Autoriser les notifications ?" que si
// Notification.requestPermission() est appelé DEPUIS un vrai tap — un appel
// automatique au démarrage (ensureNotifPerm dans boot()) est silencieusement
// ignoré. Comme les réglages sont activés par défaut, l'utilisateur n'a
// jamais besoin de taper sur un toggle déjà "on" : sans ce bouton explicite,
// la popup ne sort donc jamais et AUCUNE notification ne peut fonctionner,
// quel que soit l'état des toggles ci-dessous (trouvé en diagnostiquant un
// signalement "aucune notification n'apparaît, sur les 3 types testés").
function requestNotifPermCTA(){
  if(!('Notification'in window) || typeof Notification.requestPermission!=='function'){ toast(t('notifUnsupportedToast')); return; }
  try{
    Promise.resolve(Notification.requestPermission()).then(perm=>{
      _npCache.t=0; // la réponse change la bulle de l'Accueil tout de suite
      renderProfile();
      if(perm==='granted'){ ensurePush(); syncDailyReminderState(); toast(t('notifEnabledToast')); }
      else toast(t('notifDeniedToast'));
    }).catch(()=>toast(t('notifUnsupportedToast')));
  }catch(e){ toast(t('notifUnsupportedToast')); }
}
/* Les notifications reposent entièrement sur le Service Worker (les rappels
   serveur passent par son évènement push, l'activité en cours par
   reg.showNotification). S'il n'est pas actif, tout échoue en silence : cette
   sonde le signale au lieu de laisser croire que les réglages fonctionnent. */
let _swActive=null;
function probeServiceWorker(){
  if(!('serviceWorker'in navigator)){ _swActive=false; return; }
  navigator.serviceWorker.getRegistration()
    .then(r=>{ const ok=!!(r&&(r.active||r.installing||r.waiting)); if(ok!==_swActive){ _swActive=ok; if($('#pfSectionBody')) renderProfile(); } })
    .catch(()=>{ _swActive=false; });
}
function pfNotifHTML(){
  let h='';
  probeServiceWorker();
  if(_swActive===false){
    h+='<div class="tip" style="margin-bottom:16px;border-color:rgba(242,184,75,.45)">'+t('swInactiveTip')+'</div>';
  }
  if('Notification'in window && Notification.permission==='default'){
    // Toujours visible ici même si la bulle d'accueil a été retirée : Profil >
    // Notifications est l'endroit explicite où on vient chercher ce réglage.
    h+='<div class="row" style="align-items:center;gap:10px;padding:11px 12px;border-radius:16px;background:rgba(var(--e-rgb),.10);border:1px solid rgba(var(--e-rgb),.28);margin-bottom:16px;cursor:pointer" onclick="requestNotifPermCTA()">'+
      '<span style="display:inline-flex;flex-shrink:0">'+ICN('bell',17,'var(--e)')+'</span>'+
      '<span style="flex:1;font-size:12.5px;line-height:1.4">'+t('notifBubbleText')+' <b style="color:var(--et,var(--e))">'+t('notifBubbleAction')+'</b></span>'+
    '</div>';
  } else if('Notification'in window && Notification.permission==='denied'){
    h+='<div class="tip" style="margin-bottom:16px">'+t('notifBlockedTip')+'</div>';
  }
  h+='<div class="row" style="margin-bottom:14px"><span style="font-size:14px">'+t('trainReminders')+'</span><div class="toggle'+(P.notif!==false?' on':'')+'" onclick="toggleNotif(this)"></div></div>'+
    '<div class="row" style="margin-bottom:14px"><span style="font-size:14px">'+t('prayerNotifLabel')+'</span><div class="toggle'+(P.prayerNotif!==false?' on':'')+'" onclick="togglePrayerNotif(this)"></div></div>'+
    '<div class="row" style="margin-bottom:4px"><span style="font-size:14px">'+t('socialNotifLabel')+'</span><div class="toggle'+(P.socialNotif===true?' on':'')+'" onclick="toggleSocialNotif(this)"></div></div>'+
    '<div style="font-size:11.5px;color:var(--muted);line-height:1.45;margin-bottom:14px">'+t('socialNotifDesc')+'</div>'+
    '<div class="row" style="margin-bottom:4px"><span style="font-size:14px">'+t('mcSetting')+'</span><div class="toggle'+(P.morningCheck!==false?' on':'')+'" role="switch" aria-checked="'+(P.morningCheck!==false)+'" aria-label="'+t('mcSetting')+'" onclick="P.morningCheck=(P.morningCheck===false);this.classList.toggle(\'on\',P.morningCheck);this.setAttribute(\'aria-checked\',P.morningCheck);DB.save(\'profile\',P);haptic()"></div></div>'+
    '<div style="font-size:11.5px;color:var(--muted);line-height:1.45;margin-bottom:14px">'+t('mcSettingDesc')+'</div>'+
    '<div class="row" style="margin-bottom:14px"><span style="font-size:14px">'+t('sounds')+'</span><div class="toggle'+(P.sounds!==false?' on':'')+'" onclick="toggleSounds(this)"></div></div>'+
    // Le volume et l'écoute n'apparaissent que si les sons sont actifs : un
    // curseur sur un réglage éteint ne veut rien dire.
    (P.sounds!==false
      ? '<div style="margin-bottom:14px"><div style="font-size:13px;color:var(--muted);margin-bottom:8px">'+t('sndPackLab')+'</div>'+
          '<div class="seg-ctrl sub">'+[['soft','sndPackSoft'],['signature','sndPackSig']].map(([k,l])=>'<div class="seg-btn'+(sndPack()===k?' on':'')+'" onclick="setSndPack(\''+k+'\')">'+t(l)+'</div>').join('')+'</div>'+
          '<div style="font-size:11.5px;color:var(--muted);line-height:1.45;margin-top:7px">'+t(sndPack()==='signature'?'sndPackSigDesc':'sndPackSoftDesc')+'</div></div>'+
        '<div style="margin-bottom:14px">'+
          '<div class="row" style="margin-bottom:7px"><span style="font-size:13px;color:var(--muted)">'+t('soundVolumeLab')+'</span>'+
            '<span class="num" style="font-size:12px;color:var(--et,var(--e))" id="sndVolVal">'+Math.round(soundVol()*100)+'%</span></div>'+
          '<input type="range" min="0" max="100" step="5" value="'+Math.round(soundVol()*100)+'" style="width:100%" oninput="setSoundVol(this.value)">'+
          '<div class="pills" style="margin-top:10px;flex-wrap:wrap">'+
            [['start','sndTest1'],['tick','sndTest2'],['goal','sndTest3'],['medal','sndTest4'],['finish','sndTest5']]
              .map(x=>'<div class="pill" onclick="previewSfx(\''+x[0]+'\')">'+t(x[1])+'</div>').join('')+
          '</div>'+
        '</div>'
      : '');
  return h;
}
/* ---------- COMMENTAIRE / AVIS ----------
   Volontairement le plus simple possible : une zone de texte, un bouton.
   Envoi par mailto: (aucun service d'email tiers à configurer, aucune clé
   API à sécuriser côté serveur) — ouvre l'appli mail déjà installée sur le
   téléphone avec le message pré-rempli ; il ne reste qu'à taper "Envoyer"
   dans cette appli. FEEDBACK_EMAIL est un espace réservé, comme les crochets
   des CGU/politique de confidentialité : à remplacer par l'adresse réelle. */
const FEEDBACK_EMAIL='ikorunn@gmail.com';
function openFeedback(){
  let h='<div style="text-align:center;padding:4px 0 14px;color:var(--et,var(--e))">'+ICN('comment',40,'currentColor')+'</div>';
  h+='<div class="tip" style="margin-bottom:14px">'+t('feedbackIntro')+'</div>';
  h+='<textarea class="inp" id="fb_text" rows="6" placeholder="'+t('feedbackPh')+'"></textarea>';
  h+='<button class="btn" style="margin-top:14px" onclick="sendFeedback()">'+t('sendBtn')+'</button>';
  $('#ovProgTitle').textContent=t('feedbackTitle'); $('#progBody').innerHTML=h; $('#ovProg').style.zIndex=topZ(); openOv('ovProg');
}
function sendFeedback(){
  const txt=($('#fb_text').value||'').trim();
  if(!txt){ toast(t('feedbackEmptyToast')); return; }
  // Tant que l'adresse réelle n'a pas remplacé l'espace réservé, ouvrir le client
  // mail produirait un brouillon adressé à « [ton email...] » — et annoncer
  // « message envoyé » serait faux. On le dit franchement plutôt que de faire
  // croire à un envoi.
  if(/^\[|à compléter/.test(FEEDBACK_EMAIL)){ toast(t('feedbackNoAddressToast')); return; }
  const subject=encodeURIComponent('IKORUN — '+t('feedbackTitle'));
  const body=encodeURIComponent(txt+'\n\n—\n'+tp('feedbackSignature',P.username||P.name||'—',curLang().toUpperCase()));
  window.location.href='mailto:'+FEEDBACK_EMAIL+'?subject='+subject+'&body='+body;
  closeOv('ovProg');
  toast(t('feedbackSentToast'));
}
