/* ---- Photo & Bio ---- */
function changePhoto(){
  // Propose galerie OU appareil photo
  let h='<div class="tip" style="margin-bottom:14px">'+t('choosePhotoLab')+'</div>';
  h+='<button class="btn" style="margin-bottom:10px" onclick="pickPhotoSource(false)">'+t('fromGalleryBtn')+'</button>';
  h+='<button class="btn ghost" style="margin-bottom:10px" onclick="pickPhotoSource(true)">'+t('takePhotoBtn')+'</button>';
  if(P.photo) h+='<button class="btn ghost" style="color:var(--bad)" onclick="removePhoto();closeOv(\'ovProg\')">'+t('removePhotoBtn')+'</button>';
  $('#ovProgTitle').textContent=t('profilePhotoTitle'); $('#progBody').innerHTML=h; $('#ovProg').style.zIndex='13700'; openOv('ovProg');
}
function pickPhotoSource(useCamera){
  const inp=document.createElement('input'); inp.type='file'; inp.accept='image/*';
  if(useCamera) inp.capture='user'; // appareil photo. Sans capture = galerie
  inp.onchange=e=>{ const f=e.target.files[0]; if(!f)return; const r=new FileReader();
    r.onload=()=>{ const img=new Image(); img.onload=()=>{ openCropper(img); }; img.src=r.result; };
    r.readAsDataURL(f); };
  inp.click();
}
/* Recadrage simple : zoom + déplacement avant validation */
let _crop=null;
const CROP_VIEW=300, CROP_DPR=Math.min(3,window.devicePixelRatio||2), CROP_OUT=512;
function openCropper(img){
  closeOv('ovProg');
  _crop={img,scale:1,x:0,y:0};
  let h='<div class="tip" style="margin-bottom:12px">'+t('cropHintText')+'</div>';
  h+='<div id="cropStage" style="position:relative;width:'+CROP_VIEW+'px;height:'+CROP_VIEW+'px;max-width:100%;margin:0 auto 14px;border-radius:50%;overflow:hidden;background:#000;touch-action:none;border:2px solid var(--e)"><canvas id="cropCv" style="width:100%;height:100%;display:block"></canvas></div>';
  h+='<div class="field"><label>'+t('zoomLab')+'</label><input id="cropZoom" type="range" min="1" max="4" step="0.01" value="1" style="width:100%"></div>';
  h+='<button class="btn" onclick="applyCrop()">'+t('validatePhotoBtn')+'</button>';
  $('#ovProgTitle').textContent=t('cropTitle'); $('#progBody').innerHTML=h; $('#ovProg').style.zIndex='13700'; openOv('ovProg');
  setTimeout(initCropper,40);
}
function drawCrop(){
  const c=$('#cropCv'); if(!c)return;
  const R=CROP_VIEW*CROP_DPR;
  if(c.width!==R){ c.width=R; c.height=R; }
  const ctx=c.getContext('2d'); ctx.imageSmoothingEnabled=true; ctx.imageSmoothingQuality='high';
  const{img,scale,x,y}=_crop;
  ctx.clearRect(0,0,R,R); ctx.fillStyle='#000'; ctx.fillRect(0,0,R,R);
  const base=R/Math.min(img.width,img.height); const w=img.width*base*scale, hh=img.height*base*scale;
  ctx.drawImage(img,(R-w)/2+x*CROP_DPR,(R-hh)/2+y*CROP_DPR,w,hh);
}
function initCropper(){
  drawCrop();
  const z=$('#cropZoom'); if(z) z.oninput=()=>{ _crop.scale=+z.value; drawCrop(); };
  const stage=$('#cropStage'); if(!stage)return;
  let drag=false,lx=0,ly=0;
  stage.addEventListener('pointerdown',e=>{ drag=true; lx=e.clientX; ly=e.clientY; stage.setPointerCapture&&stage.setPointerCapture(e.pointerId); });
  stage.addEventListener('pointermove',e=>{ if(!drag)return; _crop.x+=e.clientX-lx; _crop.y+=e.clientY-ly; lx=e.clientX; ly=e.clientY; drawCrop(); });
  stage.addEventListener('pointerup',()=>drag=false);
}
function applyCrop(){
  // Rendu final haute résolution directement depuis l'image source (net, non pixelisé)
  const{img,scale,x,y}=_crop;
  const out=document.createElement('canvas'); out.width=CROP_OUT; out.height=CROP_OUT;
  const ctx=out.getContext('2d'); ctx.imageSmoothingEnabled=true; ctx.imageSmoothingQuality='high';
  ctx.fillStyle='#000'; ctx.fillRect(0,0,CROP_OUT,CROP_OUT);
  const base=CROP_OUT/Math.min(img.width,img.height); const w=img.width*base*scale, hh=img.height*base*scale;
  const ratio=CROP_OUT/CROP_VIEW; // remappe le déplacement de l'aperçu vers la sortie
  ctx.drawImage(img,(CROP_OUT-w)/2+x*ratio,(CROP_OUT-hh)/2+y*ratio,w,hh);
  P.photo=out.toDataURL('image/jpeg',0.9); saveAll(); closeOv('ovProg'); renderProfile(); toast(t('photoUpdated')); sfx&&sfx('goal');
}
function removePhoto(){ delete P.photo; saveAll(); renderProfile(); toast(t('photoRemoved')); }
function editBio(){ customPrompt(t('bioPromptLabel'),P.bio||'',v=>{ P.bio=v.slice(0,160); saveAll(); renderProfile(); },{maxLength:160}); }
/* Un fichier importé peut avoir été fabriqué puis envoyé à l'utilisateur
   (« voici ma sauvegarde »). L'ancien code recopiait le profil tel quel en ne
   nettoyant que name/bio/photo : height, weight, goal… repartaient bruts dans
   du innerHTML (audit 24/09). On ne garde désormais que les champs connus,
   chacun avec son type, et les textes sans caractère capable d'ouvrir une
   balise ou de sortir d'un attribut. pendingEmail/pendingNoPw (état interne
   d'un changement d'e-mail en cours) ne sont jamais importés. */
function stripHtmlChars(s){ return String(s).replace(/[<>"`\\]/g,''); }
// Copie profonde bornée d'une rubrique importée : nombres finis, booléens et null
// gardés tels quels, textes sans caractère HTML (<>"`\) et tronqués, tableaux
// ≤ 5000 éléments, objets ≤ 300 clés, profondeur ≤ 8. Rien d'exécutable ne peut
// traverser, quel que soit l'écran qui affiche ensuite ces données.
function cleanImportedDeep(v,depth){
  depth=depth||0; if(depth>8) return null;
  if(v===null||typeof v==='boolean') return v;
  if(typeof v==='number') return Number.isFinite(v)?v:null;
  if(typeof v==='string') return stripHtmlChars(v).slice(0,4000);
  if(Array.isArray(v)) return v.slice(0,5000).map(x=>cleanImportedDeep(x,depth+1));
  if(typeof v==='object'){ const o={}; Object.keys(v).slice(0,300).forEach(k=>{ if(k==='__proto__'||k==='constructor'||k==='prototype') return;
      // Un identifiant finit tel quel entre apostrophes dans un onclick="openPerso('…')" :
      // une apostrophe ou une parenthèse y suffirait à injecter du code. On ne garde
      // donc que les caractères qu'un vrai identifiant peut contenir.
      const val=(typeof v[k]==='string' && /^(id|key)$|Id$/.test(k)) ? v[k].replace(/[^\w.:-]/g,'').slice(0,80) : cleanImportedDeep(v[k],depth+1);
      o[stripHtmlChars(k).slice(0,80)]=val; }); return o; }
  return null;
}
function cleanImportedProfile(src){
  const o={};
  ['height','weight','hrMax','hrRest','kmWeek','kmWeekMin','kmWeekMax','soundVol','vdot','joinedAt','lum','mat','matV','hijriAdj','objRaceKm'].forEach(k=>{
    if(src[k]==null || src[k]==='') return;
    const n=Number(src[k]); if(Number.isFinite(n)) o[k]=n;
  });
  ['easyMode','bdayTheme','fetes','notif','prayerNotif','sounds','notifPromptDismissed','setupDone'].forEach(k=>{
    if(typeof src[k]==='boolean') o[k]=src[k];
  });
  const STR={name:40,username:20,bio:160,city:60,goal:80,compDate:10,bday:10,objRace:40,objTime:12,
    t5k:12,t3k:12,t10k:12,t1500:12,pb5k:12,pb3k:12,pb10k:12,pb1500:12,lang:2,mode:10,theme:20,glass:8,sndPack:12,wrap:12,ezTheme:12,
    sex:10,objGoal:40,objProfile:40,followPerso:40,planSituation:10,planLevel:6,planGap:6,objRaceName:140};
  Object.keys(STR).forEach(k=>{ if(typeof src[k]==='string') o[k]=stripHtmlChars(src[k]).slice(0,STR[k]); });
  if(Array.isArray(src.days)) o.days=src.days.filter(x=>Number.isInteger(x)&&x>=0&&x<=6).slice(0,7);
  // V4.0.0 : course du calendrier (identifiant UUID) et courses suivies
  const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
  if(typeof src.objRaceId==='string' && UUID.test(src.objRaceId)) o.objRaceId=src.objRaceId;
  if(Array.isArray(src.raceFollows)) o.raceFollows=src.raceFollows.filter(f=>f && UUID.test(f.id||'') && /^\d{4}-\d{2}-\d{2}$/.test(f.date||''))
    .slice(0,50).map(f=>({id:f.id,date:f.date,name:stripHtmlChars(f.name||'').slice(0,140),city:stripHtmlChars(f.city||'').slice(0,80)}));
  if(typeof src.photo==='string' && safePhotoUrl(src.photo)) o.photo=src.photo;
  return o;
}
/* ---------- HISTORIQUE DES PERFORMANCES (records illimités) ---------- */
const REC_DISTANCES=[['100 m',100],['200 m',200],['300 m',300],['400 m',400],['600 m',600],['800 m',800],['1000 m',1000],['1500 m',1500],['3000 m',3000],['5000 m',5000],['10 km',10000],['15 km',15000],['Semi-marathon',21097],['Marathon',42195],['Trail',0],['Cross',0]];
function openRecords(){
  let h='<button class="btn" style="margin-bottom:14px" onclick="addRecord()">'+t('addPerf')+'</button>';
  const recs=personalRecords();
  if(!recs.length) h+='<div class="card"><div class="empty"><div class="em-ic">'+ICN('medal',36,'currentColor')+'</div><div style="font-size:13px">'+t('addChronosHint')+'</div></div></div>';
  else {
    const sorted=[...RECORDS].sort((a,b)=>(a.meters||0)-(b.meters||0));
    window._recSorted=sorted;
    sorted.forEach((r,i)=>{
      const v=r.meters>=VDOT_MIN_M?vdotFromRace(r.meters,parseTime(r.time)).toFixed(1):'—';
      h+='<div class="card" style="padding:13px"><div class="row"><div><div style="font-weight:700">'+escHtml(r.dist)+' · <span class="mono" style="color:var(--et,var(--e))">'+escHtml(r.time)+'</span></div><div style="font-size:11px;color:var(--muted);margin-top:3px">'+(r.date?fmtDate(r.date):'')+(r.place?' · '+escHtml(r.place):'')+(r.meters?' · VDOT '+v:'')+'</div></div><div class="row" style="gap:4px;flex:0 0 auto">'+(r.time?'<button class="x" onclick="openShareCard(\'record\','+i+')" aria-label="'+t('share')+'">'+ICN('share',16)+'</button>':'')+'<button class="x" onclick="delRecord('+i+')" aria-label="'+t('delete')+'">'+ICN('trash',16)+'</button></div></div>'+(r.feel||r.hrAvg?'<div style="font-size:11px;color:var(--dim);margin-top:6px">'+(r.feel?escHtml(r.feel):'')+(r.hrAvg?' · '+t('avgHR')+' '+r.hrAvg:'')+(r.hrMax?' / '+t('maxHRshort')+' '+r.hrMax:'')+'</div>':'')+'</div>';
    });
    const best=bestRecord();
    if(best) h+='<div class="card" style="border-color:var(--or);text-align:center"><div class="lab" style="color:var(--or)">'+t('bestPerf')+'</div><div class="man" style="font-weight:800;font-size:18px;margin-top:4px">'+escHtml(best.dist)+' — '+escHtml(best.time)+'</div><div style="font-size:12px;color:var(--muted)">VDOT '+vdotFromRace(best.meters,parseTime(best.time)).toFixed(1)+'</div></div>';
  }
  $('#profileEditBody').innerHTML=h; $('#profileEditFoot').innerHTML=''; $('#ovProfile').querySelector('h2').textContent=t('perfHistoryTitle'); openOv('ovProfile');
}
let recTmp={};
function addRecord(){
  // Étape 1 : choisir la distance via Wheel Picker
  const names=REC_DISTANCES.map(d=>d[0]).concat([t('otherDist')]);
  openPicker({title:t('chooseDistance'),cols:[{values:names,sel:9,wide:true}],onOk:idx=>{
    if(names[idx[0]]===t('otherDist')){ pickDistance(t('customDistance'),5,km=>recordForm([(km>=1?km+' km':Math.round(km*1000)+' m'),Math.round(km*1000)])); }
    else recordForm(REC_DISTANCES[idx[0]]);
  }});
}
function recordForm(d){
  recTmp={dist:d[0],meters:d[1],timeS:d[1]>=21000?5400:(d[1]>=5000?1200:300),date:todayKey(),place:'',feel:'',competition:false};
  let h='<div style="text-align:center;margin-bottom:16px"><div class="badge" style="font-size:14px;padding:8px 16px">'+d[0]+'</div>'+
    (d[1]>0&&d[1]<VDOT_MIN_M?'<div style="font-size:12.5px;color:var(--muted);margin-top:8px;line-height:1.4">'+t('recShortNoVdot')+'</div>':'')+'</div>';
  h+='<div class="field"><label>'+t('chronoLab')+'</label><div class="inp pkfield set" id="rc_time" onclick="pickTime(\''+tp('chronoFor',d[0])+'\',recTmp.timeS,v=>{recTmp.timeS=v;document.getElementById(\'rc_time\').textContent=fmtTime(v)},'+(d[1]>=15000?'true':'false')+')">'+fmtTime(recTmp.timeS)+'</div></div>';
  h+='<div class="field"><label>'+t('dateField')+'</label><input class="inp" id="rc_date" type="date" value="'+todayKey()+'"></div>';
  h+='<div class="field"><label>'+t('placeOptional')+'</label><input class="inp" id="rc_place" placeholder="'+t('placeholderPlace')+'"></div>';
  h+='<div class="field"><label>'+t('feelOptional')+'</label><input class="inp" id="rc_feel" placeholder="'+t('feelPlaceholder')+'"></div>';
  h+='<div class="row" style="margin:14px 0"><span>'+t('officialComp')+'</span><div class="toggle" id="rc_comp" onclick="recTmp.competition=!recTmp.competition;this.classList.toggle(\'on\')"></div></div>';
  h+='<button class="btn" onclick="saveRecord()">'+t('saveThisPerf')+'</button>';
  h+='<button class="btn ghost" style="margin-top:10px" onclick="openRecords()">'+t('backBtn')+'</button>';
  $('#profileEditBody').innerHTML=h; $('#profileEditFoot').innerHTML='';
}
function saveRecord(){
  const rcDate=$('#rc_date').value;
  const guard=recordGuard(recTmp.meters,recTmp.timeS,rcDate);
  // Valeurs lues MAINTENANT : la confirmation ci-dessous est asynchrone.
  const form={date:rcDate,place:$('#rc_place').value.trim(),feel:$('#rc_feel').value.trim()};
  if(!guard.ok){
    if(guard.soft){
      customConfirm(tp('recordBigJumpConfirm',Math.round(guard.current*10)/10,Math.round(guard.implied*10)/10),()=>commitRecord(form));
      return;
    }
    toast(guard.msg); return;
  }
  commitRecord(form);
}
function commitRecord(form){
  const rcDate=form.date;
  const time=fmtTime(recTmp.timeS);
  const prevBest=RECORDS.filter(r=>r.dist===recTmp.dist).reduce((m,r)=>{ const s=parseTime(r.time); return s>0&&s<m?s:m; },Infinity);
  RECORDS.push({dist:recTmp.dist,meters:recTmp.meters,time,date:rcDate,place:form.place,feel:form.feel,competition:!!recTmp.competition});
  if(rcDate===todayKey() && prevBest<Infinity && recTmp.timeS<prevBest) setTimeout(()=>feteRecord(tp('recRunTime',recTmp.dist,time)),900);
  if(recTmp.dist==='5000 m')P.pb5k=time; if(recTmp.dist==='3000 m')P.pb3k=time; if(recTmp.dist==='1500 m')P.pb1500=time; if(recTmp.dist==='10 km')P.pb10k=time;
  P.vdot=vdotRefresh();
  saveAll(); refreshXP({animate:true}); openRecords(); toast(recTmp.competition?t('perfAddedComp'):t('perfAdded')); burst();
}
// Ajouter un record de 1500/3000/5000 m ou 10 km écrit AUSSI P.pbXX (compatibilité
// avec l'ancien profil), mais le supprimer ne le retirait pas : le record effacé
// restait affiché sur l'accueil et compté dans l'XP (audit 24/09). On recalcule le
// champ depuis les records restants, sinon depuis le chrono du profil (P.tXX).
const PB_FIELDS={'1500 m':['pb1500','t1500'],'3000 m':['pb3k','t3k'],'5000 m':['pb5k','t5k'],'10 km':['pb10k','t10k']};
function syncPbFromRecords(dist){
  const f=PB_FIELDS[dist]; if(!f) return;
  const best=RECORDS.filter(x=>x.dist===dist && x.time).sort((a,b)=>parseTime(a.time)-parseTime(b.time))[0];
  P[f[0]]=best?best.time:(P[f[1]]||'');
}
function delRecord(i){ const sorted=[...RECORDS].sort((a,b)=>(a.meters||0)-(b.meters||0)); const r=sorted[i]; RECORDS=RECORDS.filter(x=>x!==r); if(r) syncPbFromRecords(r.dist); P.vdot=vdotRefresh(); saveAll(); openRecords(); }
function computeVDOTfromRecords(){
  let best=computeVDOT();
  RECORDS.forEach(r=>{ if(r.meters>=VDOT_MIN_M&&r.time){ const v=vdotFromRace(r.meters,parseTime(r.time)); if(v>best)best=v; }});
  return best>0?clampVdot(best):0;
}
function openProfileEdit(focusId){
  $('#ovProfile').querySelector('h2').textContent=t('editProfileTitle');
  const f=(l,id,v,ty)=>'<div class="field"><label>'+l+'</label><input class="inp" id="'+id+'" value="'+escHtml(v||'')+'" '+(ty?'type="'+ty+'"':'')+'></div>';
  let h='<div class="field"><label>'+t('usernameLab')+'</label><div class="uname-wrap"><span class="uname-at">@</span><input class="inp" id="pe_username" value="'+escHtml(P.username||'')+'" autocapitalize="off" autocorrect="off" spellcheck="false"></div><div class="uname-status" id="pe_username_status">'+t('usernameHint')+'</div></div>';
  // V4.11.4 : l'identité seulement. Taille, poids et cœur ont leur assistant ; objectif, km/sem et
  // date de course se règlent dans la création du plan ; les chronos dans « Historique & records ».
  h+=f(t('firstNameLab'),'pe_name',P.name)+f(t('cityLab'),'pe_city',P.city)+f(t('birthDateLab'),'pe_bday',P.bday,'date')+
    '<div class="grp-card" style="margin-top:6px"><div class="grp-row" role="button" onclick="closeOv(\'ovProfile\');bfFlowOpen()"><div class="lr-icon">'+ICN('scale',20,'currentColor')+'</div><div class="lr-title">'+t('bodyRowLab')+'</div><div class="lr-val">'+(P.height?escHtml(P.height)+' cm':'—')+' · '+(P.weight?escHtml(P.weight)+' kg':'—')+'</div><span class="lr-chev">'+ICN('chevronR',16)+'</span></div></div>';
  $('#profileEditBody').innerHTML=h;
  $('#profileEditFoot').innerHTML='<button class="btn" onclick="saveProfileEdit()">'+t('saveBtn')+'</button>';
  openOv('ovProfile');
  peUsernameOk=true; // on ne bloque pas si le champ n'a pas changé
  wireUsernameField('pe_username','pe_username_status',ok=>{ peUsernameOk=ok; });
  if(focusId) setTimeout(()=>{ const el=$('#'+focusId); if(el){ el.scrollIntoView({block:'center'}); el.focus(); } },380);
}
let peUsernameOk=true;
async function saveProfileEdit(){
  // Bornes réalistes (audit 24/09) : 5000 kg, -5 cm, FC max 999 ou une FC de repos
  // au-dessus de la FC max étaient enregistrés tels quels et faussaient IMC,
  // calories, métabolisme, zones cardiaques et volume du plan.
  { const num=id=>{ const e=$('#'+id); const v=e?e.value.trim():''; return v===''?null:+v; };
    const h=num('pe_h'), w=num('pe_w'), hm=num('pe_hrmax'), hr=num('pe_hrrest'), km=num('pe_km');
    const bad=(v,a,b)=>v!=null && !(v>=a && v<=b);
    if(bad(h,100,250)||bad(w,25,250)||bad(hm,120,230)||bad(hr,30,120)||bad(km,0,250)||(hm!=null&&hr!=null&&hr>=hm)){ toast(t('profileValuesInvalid')); return; }
    const bd=$('#pe_bday').value; if(bd){ const age=(Date.now()-new Date(bd+'T00:00:00'))/31557600000; if(!(age>=6&&age<=100)){ toast(t('bdayInvalid')); return; } } }
  const newUsername=$('#pe_username').value.trim();
  if(newUsername && newUsername!==P.username){
    if(!usernameFormatOk(newUsername)){ toast(t('usernameInvalid')); return; }
    { const u=$('#pe_username'), st=u&&u._uname; // V3.14.0 : résultat de LA valeur saisie, pas d'une précédente
      if(u && (!st || st.v!==newUsername || st.ok===null)){ await checkUsernameLive(newUsername,$('#pe_username_status'),u); }
      const r=u&&u._uname; if(r && r.v===newUsername) peUsernameOk=(r.ok===true||r.ok==='error'); }
    if(!peUsernameOk){ toast(t('usernameNotAvailable')); return; }
    const ok=await claimUsername(newUsername);
    if(!ok){ toast(t('usernameJustTaken')); return; }
    toast(t('usernameUpdated'));
  }
  P.name=$('#pe_name').value.trim()||P.name; P.city=$('#pe_city').value.trim(); P.bday=$('#pe_bday').value;
  { const v=id=>{ const e=$('#'+id); return e?e.value.trim():null; };   // champs présents seulement dans d'anciennes versions de la fiche
    if(v('pe_h')) P.height=+v('pe_h'); if(v('pe_w')) P.weight=+v('pe_w'); if(v('pe_hrmax')) P.hrMax=+v('pe_hrmax'); if(v('pe_hrrest')) P.hrRest=+v('pe_hrrest');
    if(v('pe_km')) P.kmWeek=+v('pe_km'); if(v('pe_goal')!=null) P.goal=v('pe_goal'); if(v('pe_comp')!=null) P.compDate=v('pe_comp'); }
  // Records d'abord, comme au démarrage (initApp) : computeVDOT() seul ne lit que
  // les chronos du formulaire et remettait la VDOT à 0 pour qui avait saisi ses
  // performances à l'onboarding (qui les range dans RECORDS).
  P.vdot=vdotRefresh();
  saveAll(); closeOv('ovProfile'); renderProfile(); toast(t('profileUpdated'));
}

/* ---------- RÉGLAGES ---------- */
function resetAll(){
  customConfirm(t('confirmClearAll'),()=>{
    customConfirm(t('confirmClearAllFinal'),()=>{
      localStorage.clear();
      location.reload();
    },{danger:true});
  },{danger:true});
}

/* ============ PWA : manifest + service worker (offline-first) ============ */
function setupPWA(){
  // NE PLUS générer de manifest dynamique ici.
  //
  // Historiquement, cette fonction fabriquait un manifest en JS, l'emballait
  // dans un Blob et remplaçait le href du <link rel="manifest"> par une URL
  // blob: — contournement de l'époque où aucun manifest.json n'était déployé.
  // Depuis qu'un vrai /manifest.json existe, ce contournement était devenu la
  // CAUSE du problème : il rendait l'application non installable.
  //   - start_url:'.' / scope:'.' se résolvaient relativement à l'URL blob,
  //     donc hors de l'origine du site → critère d'installabilité en échec ;
  //   - les icônes étaient déclarées type:'image/svg+xml' alors que
  //     icon-192.png / icon-512.png sont des PNG → icônes rejetées, donc plus
  //     aucune icône valide 192/512 ;
  //   - l'URL blob finissait révoquée ("Failed to fetch" au rechargement du
  //     manifest par le navigateur).
  // Résultat : Chrome ne déclenchait jamais beforeinstallprompt, et le bouton
  // « Installer l'application » n'avait donc rien à proposer.
  //
  // Le <link rel="manifest" href="manifest.json"> statique d'index.html suffit
  // et est valide (nom, icônes PNG 192+512, start_url '/', display standalone).
  //
  // Le service worker, lui, est enregistré depuis index.html (sw.js statique).
}

/* ============ ÉTAT EN LIGNE / HORS LIGNE ET SYNCHRONISATION ============ */
function checkConnectivity(){
  const online=navigator.onLine;
  if(online){ syncOnline(true); }
  else {
    const last=lastOnlineGet()||PREFS.lastOnline||Date.now();
    const days=Math.floor((Date.now()-last)/86400000);
    if(days>=3) setTimeout(()=>toast(''+tp('offlineSinceDays',days)),1500);
  }
  return online;
}
// Dernière connexion : propre à l'appareil, gardée hors de « prefs » (sinon la clé
// repartait vers le serveur au lancement puis toutes les 5 min, pour une simple heure).
function lastOnlineGet(){ try{ return +localStorage.getItem('ik_last_online')||0; }catch(e){ return 0; } }
/* Synchronisation silencieuse quand Internet est disponible */
function syncOnline(silent){
  if(!navigator.onLine) return;
  if(silent && Date.now()-_lastScrollTouch<1000){ setTimeout(()=>syncOnline(silent),1500); return; } // évite de re-render sous le doigt
  try{ localStorage.setItem('ik_last_online',String(Date.now())); }catch(e){}
  if('lastOnline' in PREFS || 'lastSync' in PREFS){ delete PREFS.lastOnline; delete PREFS.lastSync; }
  // Recalcule/rafraîchit les données dépendantes de la date (prières, calendrier, J-X…)
  checkDayRollover(); // couvre le cas ou l'app reste affichee au passage de minuit
  try{ if($('#s-home')&&$('#s-home').classList.contains('on')) renderHome(); }catch(e){}
  try{ if($('#s-outils')&&$('#s-outils').classList.contains('on')&&outilsTab==='priere') renderPriere(); }catch(e){}
  DB.save('prefs',PREFS);
  if(!silent) toast(''+t('dataSynced'));
  nudgeScroll();
}
window.addEventListener('online',()=>{ toast(''+t('connectionRestored')); syncOnline(false); if(window._offlineBoot) scheduleResume(); else flushDirty().then(ok=>{ if(ok) toast(t('dataSynced')); }); });
window.addEventListener('offline',()=>{ toast(''+t('offlineModeAvailable')); });
// Sync silencieuse périodique tant que l'app est ouverte
setInterval(()=>{ if(navigator.onLine){ syncOnline(true); flushDirty(); } },5*60*1000);

if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',startApp); else startApp();
setTimeout(hideAppSkeleton,7000); // filet de sécurité si le réseau/l'auth traîne
setupPWA();
